) -> Result<(), Diagnostic> {
    match allocation_paths::current(program, function) {
        Some(current) => {
            ordinary_status::validate_allocation_projection(current, &function.cleanup_plan)
        }
        None => ordinary_status::validate(program, function),
    }
}

