                | S::FromUsize
                | S::Slice
                | S::Trim
                | S::MapNew
                | S::MapAdd
                | S::MapSet
                | S::MapKeyAt
                | S::FromStr
                | S::FromUtf8 => Err(refuse(
                    function,
                    expression,
                    "an uncatalogued String operation shape",
                )),
                S::Take
                | S::Len
                | S::IsEmpty
                | S::StartsWith
                | S::Contains
                | S::LenChars
                | S::Find
                | S::ToI64
                | S::ByteAt
                | S::Compare
                | S::MapGetOr
                | S::MapHas
                | S::MapLen
                | S::MapValueAt
                | S::MapRemove
                | S::F64FromI64
                | S::I64FromF64
                | S::UsizeFromI64
                | S::I64FromUsize
                | S::I64FromU8
                | S::I64FromI32
                | S::UsizeFromU8
                | S::U8FromI64
                | S::CharFromU8
                | S::CharFromI64 => Ok(()),
            };
        }
        if let Some(operation) = crate::byte_ops::by_id(callee.as_str()) {
            use crate::byte_ops::ByteOp as B;
            return match operation {
                B::Partition => Err(refuse(function, expression, "a byte partition carrier")),
                B::Copy | B::Zeroed | B::ZeroedBounded => Err(refuse(
                    function,
                    expression,
                    "an uncatalogued byte operation shape",
                )),
                B::Len
                | B::Get
                | B::Range
                | B::BytesAsSlice
                | B::ArrayAsSlice
                | B::StrAsBytes
                | B::StringAsStr
                | B::Set
                | B::Set5
                | B::Set1Or5
                | B::Set1Or6Or48 => Ok(()),
            };
        }
