        return Ok(None);
    };
    budget.child_charge(
        function,
        callee
            .as_str()
            .len()
            .min(64)
            .checked_add(1)
            .and_then(|n| n.checked_mul(32))
            .ok_or_else(|| {
                Deferred::Finite(Refusal::Profile(
                    ProfileRefusal::SelectedVecCalleeWorkOverflow,
