        _ => (
            crate::cleanup::selected_inline::selected_vector_element_inline(
                program,
                &expression.ty,
            )? == Some(element),
            OwnershipMode::Own,
        ),
    };
    if !valid_type || expression.ownership != mode {
        return Err(Deferred::Finite(Refusal::Profile(
            ProfileRefusal::SelectedVecResultTypeOrModeDisagrees,
        )));
    }
