                            .declarations
                            .declaration(template)
                            .and_then(|item| item.owner.clone())
                            .ok_or_else(|| {
                                self.error(
                                    "SPX-T231",
                                    "`super` is only allowed inside a class-method override",
                                    *method_span,
                                )
