//! Test-only differential recursive resolver; never used in production.
use super::expr_nodes::{
    PatternValue, ResolvedExpr, ResolvedExprKind, ResolvedFieldInitializer, ResolvedMatchArm,
    ResolvedMatchPattern, ResolvedMatchPatternField, ResolvedStatement,
};
use super::ids::CompilerDeclaration as CId;
use super::ids::{DeclarationId, ExpressionId, FunctionExecutionId, ValueId};
use super::monomorphize::substitute_type;
use super::nodes::{
    is_scalar_resolved_type, resolver_admits_owned_variant, DeclarationKind, OwnershipMode,
    ResolvedBinding, ResolvedImportResultKind, ResolvedMatchMode, ResolvedNativeRustImportCall,
    ResolvedType,
};
use super::type_reachability::record_args_ok;
use super::{Binding, Place, PlaceProjection, Resolver};
use crate::ast::{BinaryOp, Expr, ExprKind, MatchPattern, Statement, TypeDeclarationKind, UnaryOp};
use crate::diagnostic::Diagnostic;
use std::collections::BTreeMap;
mod block;
mod control;
mod literal_format;
mod projection;
mod static_text;

impl Resolver<'_> {
    pub(super) fn resolve_expr_recursive_reference_inner(
        &self,
        function: &FunctionExecutionId,
        expr: &Expr,
        bindings: &BTreeMap<String, Binding>,
        path: &str,
        nearest: Option<&super::ControlTarget>,
    ) -> Result<ResolvedExpr, Diagnostic> {
        if let ExprKind::VecConstructor { .. } = &expr.kind {
            return self.resolve_constructor_reference(function, expr, bindings, path, nearest);
        }
        if let Some(inspect) = self.resolve_stdin_inspection(function, expr, bindings, path)? {
            return Ok(inspect);
        }
        if matches!(expr.kind, ExprKind::Closure { .. }) {
            return self.resolve_closure(function, expr, bindings, path, true);
        }
        if let Some(reference) = self.function_reference(function, expr, bindings, path)? {
            return Ok(reference);
        }
        if let ExprKind::Call {
            name,
            type_arguments,
            args,
        } = &expr.kind
        {
            if let Some(callable) =
                self.invocation_target(function, name, bindings, path, expr.span)?
            {
                if !type_arguments.is_empty() {
                    return Err(super::function_value::error(
                        "function value call cannot have type arguments",
                    ));
                }
                let args = args
                    .iter()
                    .enumerate()
                    .map(|(i, arg)| {
                        self.resolve_expr_recursive_reference_inner(
                            function,
                            arg,
                            bindings,
                            &format!("{path}.arg.{i}"),
                            nearest,
                        )
                    })
                    .collect::<Result<_, _>>()?;
                return super::function_value::resolve::finish(
                    self.program,
                    function,
                    path,
                    expr.span,
                    callable,
                    args,
                );
            }
        }
        let id = ExpressionId::new(function, path);
        let (kind, ty, ownership) = match &expr.kind {
            ExprKind::LexicalExit { .. } => {
                control::exit(self, function, expr, bindings, path, nearest)?
            }

            ExprKind::VecConstructor { .. } => unreachable!("handled above"),
            ExprKind::Closure { .. } => unreachable!("handled above"),
            ExprKind::Int(value) => (
                ResolvedExprKind::Int(*value),
                ResolvedType::I64,
                OwnershipMode::Value,
            ),
            ExprKind::Int32(value) => (
                ResolvedExprKind::Int32(*value),
                ResolvedType::I32,
                OwnershipMode::Value,
            ),
            ExprKind::Char(value) => (
                ResolvedExprKind::Char(*value),
                ResolvedType::Char,
                OwnershipMode::Value,
            ),
            ExprKind::Uint8(value) => (
                ResolvedExprKind::Uint8(*value),
                ResolvedType::U8,
                OwnershipMode::Value,
            ),
            ExprKind::Usize(value) => (
                ResolvedExprKind::Usize(*value),
                ResolvedType::Usize,
                OwnershipMode::Value,
            ),
            ExprKind::ArrayU8(values) => (
                ResolvedExprKind::ArrayU8(values.clone()),
                ResolvedType::ArrayU8(values.len() as u32),
                OwnershipMode::Value,
            ),
            ExprKind::RepeatArrayU8 { value, count } => (
                ResolvedExprKind::RepeatArrayU8 {
                    value: *value,
                    count: *count,
                },
                ResolvedType::ArrayU8(*count),
                OwnershipMode::Value,
            ),
            ExprKind::Float32(bits) => (
                ResolvedExprKind::Float32(*bits),
                ResolvedType::F32,
                OwnershipMode::Value,
            ),
            ExprKind::Float64(bits) => (
                ResolvedExprKind::Float64(*bits),
                ResolvedType::F64,
                OwnershipMode::Value,
            ),
            ExprKind::Bool(value) => (
                ResolvedExprKind::Bool(*value),
                ResolvedType::Bool,
                OwnershipMode::Value,
            ),
            ExprKind::String(value) => static_text::owned_string(value),
            ExprKind::BorrowedUtf8Literal(value) => (
                ResolvedExprKind::BorrowedUtf8Literal(super::StaticUtf8::from_text(value)),
                ResolvedType::Str,
                OwnershipMode::Borrow,
            ),
            ExprKind::Var(name) => {
                if let Some(loan) = self.row_argument(function, expr, bindings, path.into()) {
                    return loan;
                }
                let binding = bindings.get(name).ok_or_else(|| {
                    self.error("SPX-H002", format!("unresolved value `{name}`"), expr.span)
                })?;
                (
                    ResolvedExprKind::Place(Place {
                        root: binding.id.clone(),
                        projections: Vec::new(),
                    }),
                    binding.ty.clone(),
                    binding.ownership,
                )
            }
            ExprKind::Call {
                name,
                type_arguments,
                args,
            } => {
                if let Some(import_id) = self.declarations.native_rust_import_id(name).cloned() {
                    let import = self
                        .program
                        .interfaces()
                        .iter()
                        .flat_map(|interface| &interface.imports)
                        .find(|import| import.stable_id == import_id.as_str())
                        .expect("native Rust import index is built from source imports");
                    if !type_arguments.is_empty() || args.len() != import.params.len() {
                        return Err(self.error(
                            "SPX-B107",
                            "Native Rust Interop declaration set is unsupported: scalar value signature required",
                            expr.span,
                        ));
                    }
                    let args = args
                        .iter()
                        .enumerate()
                        .map(|(index, argument)| {
                            self.resolve_expr_recursive_reference_inner(
                                function,
                                argument,
                                bindings,
                                &format!("{path}.native-rust-arg.{index}"),
                                nearest,
                            )
                        })
                        .collect::<Result<Vec<_>, _>>()?;
                    for (argument, parameter) in args.iter().zip(&import.params) {
                        if argument.ty != self.resolve_type(&parameter.ty, parameter.span)? {
                            return Err(self.error(
                                "SPX-B107",
                                "Native Rust Interop declaration set is unsupported: scalar value signature required",
                                argument.span,
                            ));
                        }
                    }
                    let (result, ty) =
                        self.resolve_native_rust_result(&import.result, expr.span)?;
                    return Ok(ResolvedExpr {
                        id,
                        ty,
                        ownership: result.ownership(),
                        kind: ResolvedExprKind::NativeRustImportCall(
                            ResolvedNativeRustImportCall {
                                expression: ExpressionId::new(function, path),
                                import: import_id,
                                args,
                                result,
                            },
                        ),
                        span: expr.span,
                    });
                }
                if crate::vec_ops::field_unique::literal_call(name)
                    || name == crate::vec_ops::field_update::NAME
                {
                    let (element, callee) =
                        self.prepare_sort_by(function, expr, type_arguments, args)?;
                    let count = if name == crate::vec_ops::field_update::NAME {
                        3
                    } else {
                        1
                    };
                    let values = args[..count]
                        .iter()
                        .enumerate()
                        .map(|(index, arg)| {
                            self.resolve_expr_recursive_reference_inner(
                                function,
                                arg,
                                bindings,
                                &format!("{path}.arg.{index}"),
                                nearest,
                            )
                        })
                        .collect::<Result<Vec<_>, _>>()?;
                    return self.finish_sort_by(function, expr.span, path, element, callee, values);
                }
                if name == crate::vec_field::NAME {
                    let (element, field) =
                        self.prepare_vec_field(function, expr, type_arguments, args)?;
                    let values = args[..2]
                        .iter()
                        .enumerate()
                        .map(|(index, arg)| {
                            self.resolve_expr_recursive_reference_inner(
                                function,
                                arg,
                                bindings,
                                &format!("{path}.arg.{index}"),
                                nearest,
                            )
                        })
                        .collect::<Result<Vec<_>, _>>()?;
                    return self
                        .finish_vec_field(function, expr.span, path, element, field, values);
                }
                if name == crate::literal_format::NAME {
                    return self.resolve_literal_format_reference(
                        function,
                        expr,
                        bindings,
                        path,
                        type_arguments,
                        args,
                        id,
                    );
                }
                if let Some(op) = crate::string_ops::by_name(name)
                    .filter(|_| crate::map_ops::by_generic_name(name, type_arguments).is_none())
                {
                    // Oracle parity: the recursive-reference resolver admits string operations exactly like the iterative resolver.
                    if !type_arguments.is_empty() {
                        return Err(self.error(
                            "SPX-H006",
                            format!("string operation `{name}` has type arguments"),
                            expr.span,
                        ));
                    }
                    if args.len() != op.arity() {
                        return Err(self.error(
                            "SPX-H006",
                            format!(
                                "string operation `{name}` expects {} arguments, received {}",
                                op.arity(),
                                args.len()
                            ),
                            expr.span,
                        ));
                    }
                    let args = args
                        .iter()
                        .enumerate()
                        .map(|(index, argument)| {
                            self.resolve_expr_recursive_reference_inner(
                                function,
                                argument,
                                bindings,
                                &format!("{path}.arg.{index}"),
                                nearest,
                            )
                        })
                        .collect::<Result<Vec<_>, _>>()?;
                    for (index, argument) in args.iter().enumerate() {
                        if argument.ty != op.param_types()[index] {
                            let expected = &op.param_types()[index];
                            return Err(self.error(
                                "SPX-H006",
                                format!(
                                    "string operation `{}` argument {} expects `{}`, received `{}`",
                                    op.name(),
                                    index,
                                    expected.identity_key(),
                                    argument.ty.identity_key()
                                ),
                                argument.span,
                            ));
                        }
                    }
                    let ty = op.return_type();
                    let ownership =
                        self.expression_ownership(&ty, OwnershipMode::Own, expr.span)?;
                    return Ok(ResolvedExpr {
                        id,
                        ty,
                        ownership,
                        kind: ResolvedExprKind::Call {
                            callee: op.resolved_id(),
                            type_arguments: Vec::new(),
                            instance: None,
                            args,
                        },
                        span: expr.span,
                    });
                }
                if let Some(op) = crate::str_ops::by_name(name) {
                    if !type_arguments.is_empty() {
                        return Err(self.error(
                            "SPX-H006",
