                    .declarations
                    .declaration(matched_type)
                    .map(|item| item.kind);
                if !matches!(
                    matched_kind,
                    Some(DeclarationKind::Record | DeclarationKind::Variant)
                ) {
                    return Err(self.error(
                        "SPX-H001",
                        "cannot resolve match on a non-record/non-variant value",
                        expr.span,
                    ));
                }
