                                    &field_template,
                                    &matched_type,
                                    &instance_arguments,
                                )?;
                                let ownership = self.function_expression_ownership(
                                    function,
                                    &field_ty,
                                    match mode {
                                        ResolvedMatchMode::Own => OwnershipMode::Own,
                                        ResolvedMatchMode::Borrow => OwnershipMode::Borrow,
                                        ResolvedMatchMode::Value => OwnershipMode::Value,
                                    },
                                    field.span,
                                )?;
                                let binding = ResolvedBinding {
                                    id: ValueId::local(
                                        function,
                                        &format!("{path}.arm.{arm_index}.binding.{field_index}"),
                                    ),
                                    name: field.binding.clone(),
                                    ownership,
                                    ty: field_ty.clone(),
                                    span: field.binding_span,
                                };
                                arm_bindings.insert(
                                    field.binding.clone(),
                                    Binding {
                                        traversal_row: None,
                                        id: binding.id.clone(),
                                        ty: field_ty,
                                        ownership,
                                        mutable: false,
                                    },
                                );
