                (
                    ResolvedExprKind::ConstructVariant {
                        variant,
                        case,
                        fields: resolved_fields,
                    },
                    ty,
                    ownership,
                )
            }
            ExprKind::Match {
                mode,
                scrutinee,
                arms,
            } => {
                let mode = ResolvedMatchMode::from(*mode);
                let scrutinee = self.resolve_expr_recursive_reference_inner(
                    function,
                    scrutinee,
                    bindings,
                    &format!("{path}.scrutinee"),
                    nearest,
                )?;
                if matches!(
                    scrutinee.ty,
                    ResolvedType::I64
                        | ResolvedType::I32
                        | ResolvedType::U8
                        | ResolvedType::Usize
                        | ResolvedType::Char
                        | ResolvedType::Bool
                ) {
                    if mode != ResolvedMatchMode::Value {
                        return Err(self.error(
                            "SPX-O117",
                            "explicit match ownership modes require a non-Copy record scrutinee",
                            expr.span,
                        ));
                    }
                    if arms.is_empty() {
                        return Err(self.error(
                            "SPX-H006",
                            "resolved match has no arms",
                            expr.span,
                        ));
                    }
                    self.validate_refutable_match_admission(&scrutinee.ty, arms)?;
                    let mut resolved_arms: Vec<ResolvedMatchArm> = Vec::with_capacity(arms.len());
                    for (arm_index, arm) in arms.iter().enumerate() {
                        let mut arm_bindings = bindings.clone();
                        let pattern = match &arm.pattern {
                            MatchPattern::Wildcard { .. } => ResolvedMatchPattern::Wildcard,
                            MatchPattern::Binding { name, .. } => {
                                let binding = ResolvedBinding {
                                    id: ValueId::local(
                                        function,
                                        &format!("{path}.arm.{arm_index}.binding"),
                                    ),
                                    name: name.clone(),
                                    ownership: OwnershipMode::Value,
                                    ty: scrutinee.ty.clone(),
                                    span: arm.pattern.span(),
                                };
                                arm_bindings.insert(
                                    name.clone(),
                                    Binding {
                                        traversal_row: None,
                                        id: binding.id.clone(),
                                        ty: binding.ty.clone(),
                                        ownership: OwnershipMode::Value,
                                        mutable: false,
                                    },
                                );
                                ResolvedMatchPattern::Binding(binding)
                            }
                            MatchPattern::Literal { value, .. } => {
                                ResolvedMatchPattern::Literal(PatternValue::from_ast(*value))
                            }
                            MatchPattern::Or { alternatives, .. } => ResolvedMatchPattern::Or(
                                alternatives
                                    .iter()
                                    .map(|alternative| match alternative {
                                        MatchPattern::Literal { value, .. } => {
                                            ResolvedMatchPattern::Literal(PatternValue::from_ast(
                                                *value,
                                            ))
                                        }
                                        _ => unreachable!("or-pattern alternatives are literals"),
                                    })
                                    .collect(),
                            ),
                            MatchPattern::Variant { .. } | MatchPattern::Record { .. } => {
                                return Err(self.error(
                                    "SPX-H001",
                                    "aggregate pattern has a Copy-scalar scrutinee",
                                    arm.span,
                                ));
                            }
                        };
                        let guard = match &arm.guard {
                            Some(guard) => {
                                let resolved_guard = self.resolve_expr_recursive_reference_inner(
                                    function,
                                    guard.as_ref(),
                                    &arm_bindings,
                                    &format!("{path}.arm.{arm_index}.guard"),
                                    nearest,
                                )?;
                                if resolved_guard.ty != ResolvedType::Bool {
                                    return Err(self.error(
                                        "SPX-T256",
                                        format!(
                                            "match guard must be bool; received {}",
                                            resolved_guard.ty.identity_key()
                                        ),
                                        arm.span,
                                    ));
                                }
                                Some(Box::new(resolved_guard))
                            }
                            None => None,
                        };
                        let value = self.resolve_expr_recursive_reference_inner(
                            function,
                            &arm.value,
                            &arm_bindings,
                            &format!("{path}.arm.{arm_index}.value"),
                            nearest,
                        )?;
                        if let Some(first) = super::lexical_exit::reachable_arm(&resolved_arms) {
                            if value.ty != ResolvedType::Never
                                && (first.value.ty != value.ty
                                    || first.value.ownership != value.ownership)
                            {
                                return Err(self.error(
                                    "SPX-T259",
                                    format!(
                                        "match arms disagree on the result type; expected {}",
                                        first.value.ty.identity_key()
                                    ),
                                    arm.span,
                                ));
                            }
                        }
                        resolved_arms.push(ResolvedMatchArm {
                            pattern,
                            guard,
                            value,
                            span: arm.span,
                        });
                    }
                    let normal =
                        super::lexical_exit::normal_arm(&resolved_arms).expect("match has arms");
                    return Ok(ResolvedExpr {
                        id: ExpressionId::new(function, path),
                        ty: normal.value.ty.clone(),
                        ownership: normal.value.ownership,
                        kind: ResolvedExprKind::Match {
                            mode,
                            scrutinee: Box::new(scrutinee),
                            arms: resolved_arms,
                        },
                        span: expr.span,
                    });
                }
                let refutable_syntax = super::resolve_variant_or::has_scalar_only_syntax(
                    arms,
                    mode == ResolvedMatchMode::Value
                        && crate::variant_guards::copy_variant(&self.declarations, &scrutinee.ty),
                );
                if refutable_syntax {
                    return Err(self.error(
                        "SPX-T254",
                        format!(
                            "guards and literal/or/binding patterns require a Copy-scalar \
                             scrutinee (i64/i32/u8/char/bool); received {}",
                            scrutinee.ty.identity_key()
                        ),
                        expr.span,
                    ));
                }
                let ResolvedType::Nominal {
                    declaration: matched_type,
                    arguments,
                } = &scrutinee.ty
                else {
                    return Err(self.error(
                        "SPX-H001",
                        "cannot resolve match on a non-record/non-variant value",
                        expr.span,
                    ));
                };
                let matched_kind = self
                    .declarations
                    .declaration(matched_type)
                    .map(|item| item.kind);
                if !matches!(
                    matched_kind,
                    Some(DeclarationKind::Record | DeclarationKind::Variant)
                ) {
                    return Err(self.error(
                        "SPX-H001",
                        "cannot resolve match on a non-record/non-variant value",
                        expr.span,
                    ));
                }
                let matched_kind = matched_kind.expect("matched kind checked above");
                let facts = self.declarations.type_facts(&scrutinee.ty).ok_or_else(|| {
                    self.error("SPX-H006", "match scrutinee has no type facts", expr.span)
                })?;
                match (matched_kind, mode) {
                    (DeclarationKind::Variant, ResolvedMatchMode::Value)
                        if facts.copy && scrutinee.ownership == OwnershipMode::Value => {}
                    (DeclarationKind::Variant, ResolvedMatchMode::Own)
                        if resolver_admits_owned_variant(&self.declarations, &scrutinee.ty)
                            && facts.needs_drop
                            && !facts.copy
                            && scrutinee.ownership == OwnershipMode::Own => {}
                    (DeclarationKind::Variant, ResolvedMatchMode::Borrow)
                        if (resolver_admits_owned_variant(&self.declarations, &scrutinee.ty)
                            || super::workspace_link::native_owner::resolver_ri06_regex_result(
                                self.program,
                                &scrutinee.ty,
                            ))
                            && facts.needs_drop
                            && !facts.copy
                            && matches!(
                                scrutinee.ownership,
                                OwnershipMode::Own | OwnershipMode::Borrow
                            )
                            && matches!(
                                &scrutinee.kind,
                                ResolvedExprKind::Place(place) if place.projections.is_empty()
                            ) => {}
                    (DeclarationKind::Variant, _) => {
                        return Err(self.error(
                            "SPX-O117",
                            "match ownership mode disagrees with the admitted variant scrutinee",
                            expr.span,
                        ));
                    }
                    (DeclarationKind::Record, ResolvedMatchMode::Value)
                        if facts.copy && scrutinee.ownership == OwnershipMode::Value => {}
                    (DeclarationKind::Record, ResolvedMatchMode::Own)
                        if facts.needs_drop
                            && !facts.copy
                            && scrutinee.ownership == OwnershipMode::Own => {}
                    (DeclarationKind::Record, ResolvedMatchMode::Borrow)
                        if facts.needs_drop
                            && !facts.copy
                            && matches!(
                                scrutinee.ownership,
                                OwnershipMode::Own | OwnershipMode::Borrow
                            )
                            && matches!(scrutinee.kind, ResolvedExprKind::Place(_)) => {}
                    (DeclarationKind::Record, _) => {
                        return Err(self.error(
                            "SPX-O117",
                            "match ownership mode disagrees with the record scrutinee",
                            expr.span,
                        ));
                    }
                    _ => unreachable!("matched kind was restricted above"),
                }
                let instance_arguments = arguments.clone();
                let matched_type = matched_type.clone();
                let mut resolved_arms = Vec::with_capacity(arms.len());
                for (arm_index, arm) in arms.iter().enumerate() {
                    let mut arm_bindings = bindings.clone();
                    let pattern = match &arm.pattern {
                        MatchPattern::Wildcard { span }
                            if matched_kind == DeclarationKind::Variant
                                && mode != ResolvedMatchMode::Value =>
                        {
                            return Err(self.error(
                                "SPX-O117",
                                "explicit ownership variant match requires every case pattern",
                                *span,
                            ));
                        }
                        MatchPattern::Wildcard { .. } => ResolvedMatchPattern::Wildcard,
                        MatchPattern::Variant {
                            case_name, fields, ..
                        } => {
                            if matched_kind != DeclarationKind::Variant {
                                return Err(self.error(
                                    "SPX-H001",
                                    "variant pattern has a record scrutinee",
                                    arm.span,
                                ));
                            }
                            let case = self
                                .declarations
                                .case_id(&matched_type, case_name)
                                .cloned()
                                .ok_or_else(|| {
                                    self.error(
                                        "SPX-H001",
                                        format!("unresolved case `{matched_type}::{case_name}`"),
                                        arm.span,
                                    )
                                })?;
                            let mut resolved_fields = Vec::with_capacity(fields.len());
                            for (field_index, field) in fields.iter().enumerate() {
                                let field_id = self
                                    .declarations
                                    .field_id(&case, &field.name)
                                    .cloned()
                                    .ok_or_else(|| {
                                        self.error(
                                            "SPX-H001",
                                            format!(
                                                "unresolved pattern field `{case}.{}`",
                                                field.name
                                            ),
                                            field.span,
                                        )
                                    })?;
                                let field_template = self
                                    .declarations
                                    .case_fields(&case)
                                    .and_then(|items| items.iter().find(|item| item.id == field_id))
                                    .map(|item| item.ty.clone())
                                    .ok_or_else(|| {
                                        self.error(
                                            "SPX-H001",
                                            format!("pattern field `{field_id}` has no type"),
                                            field.span,
                                        )
                                    })?;
                                let field_ty = substitute_type(
                                    &field_template,
                                    &matched_type,
                                    &instance_arguments,
                                )?;
                                let ownership = self.function_expression_ownership(
                                    function,
                                    &field_ty,
                                    match mode {
                                        ResolvedMatchMode::Own => OwnershipMode::Own,
                                        ResolvedMatchMode::Borrow => OwnershipMode::Borrow,
                                        ResolvedMatchMode::Value => OwnershipMode::Value,
                                    },
                                    field.span,
                                )?;
                                let binding = ResolvedBinding {
                                    id: ValueId::local(
                                        function,
                                        &format!("{path}.arm.{arm_index}.binding.{field_index}"),
                                    ),
                                    name: field.binding.clone(),
                                    ownership,
                                    ty: field_ty.clone(),
                                    span: field.binding_span,
                                };
                                arm_bindings.insert(
                                    field.binding.clone(),
                                    Binding {
                                        traversal_row: None,
                                        id: binding.id.clone(),
                                        ty: field_ty,
                                        ownership,
                                        mutable: false,
                                    },
                                );
                                resolved_fields.push(ResolvedMatchPatternField {
                                    field: field_id,
                                    binding,
                                });
                            }
                            ResolvedMatchPattern::Variant {
                                variant: matched_type.clone(),
                                case,
                                fields: resolved_fields,
                            }
                        }
                        MatchPattern::Record {
                            type_name,
                            fields,
                            span,
                            ..
                        } => {
                            if matched_kind != DeclarationKind::Record {
                                return Err(self.error(
                                    "SPX-H001",
                                    "record pattern has a variant scrutinee",
                                    arm.span,
                                ));
                            }
                            self.resolve_record_match_pattern(
                                function,
                                &scrutinee.ty,
                                type_name,
                                fields,
                                &mut arm_bindings,
                                &format!("{path}.arm.{arm_index}.record"),
                                *span,
                                mode,
                            )?
                        }
                        MatchPattern::Or { alternatives, span } if arm.pattern.is_variant_or() => {
                            self.resolve_variant_or_pattern(
                                &matched_type,
                                matched_kind,
                                mode,
                                alternatives,
                                *span,
                            )?
                        }
                        MatchPattern::Literal { span, .. }
                        | MatchPattern::Or { span, .. }
                        | MatchPattern::Binding { span, .. } => {
                            return Err(self.error(
                                "SPX-T254",
                                "guards and literal/or/binding patterns require a \
                                 Copy-scalar scrutinee",
                                *span,
                            ));
                        }
                    };
                    let guard = self.resolve_variant_guard_reference(
                        function,
                        arm.guard.as_deref(),
                        &arm_bindings,
                        &format!("{path}.arm.{arm_index}.guard"),
                    )?;
                    let value = self.resolve_expr_recursive_reference_inner(
                        function,
                        &arm.value,
                        &arm_bindings,
                        &format!("{path}.arm.{arm_index}.value"),
                        nearest,
                    )?;
                    resolved_arms.push(ResolvedMatchArm {
                        pattern,
                        guard,
                        value,
                        span: arm.span,
                    });
                }
                let first = super::lexical_exit::normal_arm(&resolved_arms).ok_or_else(|| {
                    self.error("SPX-H006", "resolved match has no arms", expr.span)
                })?;
                let ty = first.value.ty.clone();
                let ownership = first.value.ownership;
                (
                    ResolvedExprKind::Match {
                        mode,
                        scrutinee: Box::new(scrutinee),
                        arms: resolved_arms,
                    },
                    ty,
                    ownership,
                )
            }
            ExprKind::Try { operand } => {
                let operand = self.resolve_expr_recursive_reference_inner(
                    function,
                    operand,
                    bindings,
                    &format!("{path}.operand"),
                    nearest,
                )?;
                let operand_type = operand.ty.clone();
                let ResolvedType::Nominal {
                    declaration,
                    arguments,
                } = &operand_type
                else {
                    return Err(self.error(
                        "SPX-H006",
                        "resolved `?` operand is not the ordinary Result",
                        expr.span,
                    ));
                };
                let residual_type = self.resolve_try_result_type(function, expr.span)?;
                match (declaration.as_str(), arguments.as_slice()) {
                    (crate::prelude::RESULT_ID, [ok_type, _error_type]) => {
                        super::owned_result_try::resolve_result(operand, residual_type, ok_type)
                    }
                    (crate::prelude::OPTION_ID, [some_type]) => (
                        ResolvedExprKind::TryOption {
                            operand: Box::new(operand),
                            option: DeclarationId::new(crate::prelude::OPTION_ID),
                            some_case: DeclarationId::new(crate::prelude::OPTION_SOME_ID),
                            some_field: DeclarationId::new(crate::prelude::OPTION_SOME_VALUE_ID),
                            none_case: DeclarationId::compiler(CId::OptionNone),
                            residual_type,
                        },
                        some_type.clone(),
                        OwnershipMode::Value,
                    ),
                    _ => {
                        return Err(self.error(
                            "SPX-H006",
                            "resolved `?` operand is not an ordinary Result or Option",
                            expr.span,
                        ));
                    }
                }
            }
            // Resumable Effects (issues #204, #296): mirrors `Frame::FinishYield` in the iterative resolver -- `ty` is the enclosing function's declared
            // response type read from its AST `yields` clause (request type if none resolves), and `hir::resolve_yield` still checks and retags every site
            // once resolution finishes.
            ExprKind::Yield { request } => {
                let request = self.resolve_expr_recursive_reference_inner(
                    function,
                    request,
                    bindings,
                    &format!("{path}.request"),
                    nearest,
                )?;
                let ty = self.yield_answer_type(function, &request.ty);
                (
                    ResolvedExprKind::Yield {
                        request: Box::new(request),
                    },
                    ty,
                    OwnershipMode::Value,
                )
            }
            ExprKind::UpdateRecord { base, fields } => {
                let base = self.resolve_expr_recursive_reference_inner(
                    function,
                    base,
                    bindings,
                    &format!("{path}.base"),
                    nearest,
                )?;
                let ResolvedType::Nominal {
                    declaration: record,
                    arguments: _,
                } = &base.ty
                else {
                    return Err(self.error(
                        "SPX-H001",
                        "cannot resolve a record update on a non-record value",
                        expr.span,
                    ));
                };
                if self
                    .declarations
                    .declaration(record)
                    .is_none_or(|item| item.kind != DeclarationKind::Record)
                {
                    return Err(self.error(
                        "SPX-H001",
                        "cannot resolve a record update on a non-record value",
                        expr.span,
                    ));
                }
                let record = record.clone();
                let mut resolved_fields = Vec::with_capacity(fields.len());
                for (index, initializer) in fields.iter().enumerate() {
                    let field = self
                        .declarations
                        .field_id(&record, &initializer.name)
                        .cloned()
                        .ok_or_else(|| {
                            self.error(
                                "SPX-H001",
                                format!(
                                    "unresolved replacement field `{}.{}`",
                                    record, initializer.name
                                ),
                                initializer.name_span,
                            )
                        })?;
                    let value = self.resolve_expr_recursive_reference_inner(
                        function,
                        &initializer.value,
                        bindings,
                        &format!("{path}.field.{index}.value"),
                        nearest,
                    )?;
                    resolved_fields.push(ResolvedFieldInitializer { field, value });
                }
                let ty = base.ty.clone();
                let ownership = self.expression_ownership(&ty, OwnershipMode::Own, expr.span)?;
                (
                    ResolvedExprKind::UpdateRecord {
                        base: Box::new(base),
                        record,
                        fields: resolved_fields,
                    },
                    ty,
                    ownership,
                )
            }
            // The test-only reference resolver never walks class-method bodies; `super` resolution is owned by the iterative resolver.
            ExprKind::SuperMethod { method_span, .. } => {
                return Err(self.error(
                    "SPX-T231",
                    "`super` is only allowed inside a class-method override",
                    *method_span,
                ));
            }
            ExprKind::Project { base, field, .. } => {
                if let Some(value) =
                    super::resolve_for::record::project(self, function, expr, bindings, path)?
                {
                    return Ok(value);
                }
                self.resolve_projection_reference(function, expr, base, field, bindings, path)?
            }
        };
        Ok(ResolvedExpr {
            id,
            ty,
            ownership,
            kind,
            span: expr.span,
        })
    }
}

