//! Validation-only authentication of compiler-owned `Vec<T>` calls.

use super::*;

pub(super) fn reject_reserved_identities(program: &ResolvedProgram) -> Result<(), Diagnostic> {
    for declaration in program.declarations.declarations() {
        reject_reserved_declaration(declaration)?;
    }
    for function in &program.functions {
        reject_reserved_function(function)?;
    }
    for template in &program.function_templates {
        reject_reserved_template(template)?;
    }
    for instance in &program.function_instances {
        reject_reserved_function(&instance.function)?;
    }
    Ok(())
}

pub(super) fn reject_reserved_declaration(declaration: &Declaration) -> Result<(), Diagnostic> {
    if crate::vec_ops::by_id(declaration.id.as_str()).is_some()
        || declaration.id.as_str() == crate::vec_field::ID
        || declaration.name == crate::vec_field::NAME
        || crate::vec_ops::by_name(&declaration.name).is_some()
    {
        return Err(hir_error(format!(
            "resolved {:?} declaration `{}` aliases a compiler-owned vector operation",
            declaration.kind, declaration.id
        )));
    }
    Ok(())
}

pub(super) fn reject_reserved_function(function: &ResolvedFunction) -> Result<(), Diagnostic> {
    if crate::vec_ops::by_id(function.id.as_str()).is_some()
        || function.id.as_str() == crate::vec_field::ID
        || function.name == crate::vec_field::NAME
        || crate::vec_ops::by_name(&function.name).is_some()
    {
        return Err(hir_error(format!(
            "resolved function `{}` aliases a compiler-owned vector operation",
            function.id
        )));
    }
    Ok(())
}

pub(super) fn reject_reserved_template(
    template: &ResolvedFunctionTemplate,
) -> Result<(), Diagnostic> {
    if crate::vec_ops::by_id(template.id.as_str()).is_some()
        || template.id.as_str() == crate::vec_field::ID
        || template.name == crate::vec_field::NAME
        || crate::vec_ops::by_name(&template.name).is_some()
    {
        return Err(hir_error(format!(
            "resolved function template `{}` aliases a compiler-owned vector operation",
            template.id
        )));
    }
    Ok(())
}

pub(super) fn is_type(
    declarations: &DeclarationIndex,
    declaration: &DeclarationId,
    arguments: &[ResolvedType],
) -> bool {
    declaration.as_str() == crate::prelude::VEC_ID
        && arguments.len() == 1
        && (crate::vec_ops::resolved_vec_element_is_admitted(&arguments[0])
            || crate::hir::copy_record_collection::admitted(declarations, &arguments[0])
            || crate::hir::owned_leaf_collection::layout(declarations, &arguments[0]).is_some()
            || crate::hir::owned_record_collection::is_admitted_owned_record_collection_element(
                declarations,
                &arguments[0],
            ))
}

/// `true` when `ty` is a compiler-owned bounded `Vec` carrier, including the
/// SPX-AI-019 owned-record element the front end admits but no backend
/// executes.
pub(super) fn is_owned_vec_carrier(program: &ResolvedProgram, ty: &ResolvedType) -> bool {
    crate::cleanup::is_owned_bounded_vec_type(ty)
        || crate::hir::copy_record_collection::is_vec(&program.declarations, ty)
        || crate::hir::owned_leaf_collection::is_vec(&program.declarations, ty)
        || crate::hir::owned_record_collection::is_owned_record_vec_type(&program.declarations, ty)
}

pub(super) fn is_call(callee: &DeclarationId, instance: &Option<FunctionInstanceId>) -> bool {
    instance.is_none() && crate::vec_ops::by_id(callee.as_str()).is_some()
}

pub(super) fn signature(
    declarations: &DeclarationIndex,
    callee: &DeclarationId,
    type_arguments: &[ResolvedType],
    instance: &Option<FunctionInstanceId>,
    args: &[ResolvedExpr],
) -> Result<Option<(Vec<ResolvedParam>, ResolvedType)>, Diagnostic> {
    let Some(op) = crate::vec_ops::by_id(callee.as_str()) else {
        return Ok(None);
    };
    if instance.is_some()
        || type_arguments.len() != 1
        || !crate::hir::owned_leaf_collection::vec_operation_admitted(
            declarations,
            op,
            &type_arguments[0],
        )
        || args.len() != op.arity()
    {
        return Err(hir_error("invalid vector operation call shape"));
    }
    if op == crate::vec_ops::VecOp::StrAt && !crate::vec_ops::string_slot::arguments(args) {
        return Err(hir_error(crate::vec_ops::string_slot::SHAPE));
    }
    if op == crate::vec_ops::VecOp::SortBy
        && crate::vec_ops::sort_keys::replay(declarations, &type_arguments[0], callee.as_str())
            .is_none()
    {
        return Err(hir_error(
            "explicit sort key nominal/field/layout/direction descriptor is forged or stale",
        ));
    }
    if op == crate::vec_ops::VecOp::UniqueBy
        && (!crate::vec_ops::field_unique::arguments(args, &type_arguments[0])
            || crate::vec_ops::field_unique::replay(
                declarations,
                &type_arguments[0],
                callee.as_str(),
            )
            .is_none())
    {
        return Err(hir_error(
            "borrowed field uniqueness root/nominal/field/layout descriptor is forged or stale",
        ));
    }
    Ok(Some((
        crate::vec_ops::resolved_params_in(declarations, op, &type_arguments[0]),
        if callee.as_str() == crate::vec_ops::string_slot::BYTES_ID {
            ResolvedType::SliceU8
        } else {
            op.resolved_return_type(&type_arguments[0])
        },
    )))
}

