pub(crate) fn selected_for_source(source: &str) -> (&'static str, Vec<u8>, String) {
    let Ok(program) = crate::parse(source, "<prelude-selection>") else {
        return (SCHEMA_V1, contract_bytes_v1(), digest_text_v1());
    };
    selected_for_program(&program)
}

pub(crate) fn selected_for_program(program: &dyn ProgramSource) -> (&'static str, Vec<u8>, String) {
    let (sort_keys, static_text, string_slots) = sort_keys::selection(program);
    if crate::vec_ops::field_update::source_uses(program) {
        (
            SCHEMA_V19,
            self::field_update::contract_bytes(),
            self::field_update::digest_text(),
        )
    } else if crate::vec_ops::field_unique::source_uses(program) {
        (
            SCHEMA_V18,
            self::field_unique::contract_bytes(),
            self::field_unique::digest_text(),
        )
    } else if string_slots {
        (
            SCHEMA_V17,
            self::string_slots::contract_bytes(),
            self::string_slots::digest_text(),
        )
    } else if static_text {
        (
            SCHEMA_V16,
            self::static_text::contract_bytes(),
            self::static_text::digest_text(),
        )
    } else if sort_keys {
        (
            SCHEMA_V15,
            sort_keys::contract_bytes(),
            sort_keys::digest_text(),
        )
    } else if owned_leaf::program_uses(program) {
        (
            SCHEMA_V14,
            owned_leaf::contract_bytes(),
            owned_leaf::digest_text(),
        )
    } else if crate::map_ops::program_uses(program) {
        (SCHEMA_V13, contract_bytes_v13(), digest_text_v13())
    } else if crate::vec_ops::program_uses_sort(program) {
        (SCHEMA_V12, contract_bytes_v12(), digest_text_v12())
    } else if crate::source_verify::program_uses_record_iterator(program) {
        (SCHEMA_V11, contract_bytes_v11(), digest_text_v11())
    } else if crate::stdin_stream_ops::program_uses(program) {
        (SCHEMA_V10, contract_bytes_v10(), digest_text_v10())
    } else if crate::list_ops::program_uses_list(program) {
        (SCHEMA_V9, contract_bytes_v9(), digest_text_v9())
    } else if crate::iterator_ops::program_uses_owned_iterator(program) {
        (SCHEMA_V8, contract_bytes_v8(), digest_text_v8())
    } else if crate::iterator_ops::program_uses_iterator(program) {
        (SCHEMA_V7, contract_bytes_v7(), digest_text_v7())
    } else if crate::vec_ops::program_uses_owned_payload(program) {
        (SCHEMA_V6, contract_bytes_v6(), digest_text_v6())
    } else if crate::box_ops::program_uses_owned_payload(program) {
        (SCHEMA_V5, contract_bytes_v5(), digest_text_v5())
    } else if program_uses_box(program) {
        (SCHEMA_V4, contract_bytes_v4(), digest_text_v4())
    } else if program_uses_vec_v3(program) {
        (SCHEMA_V3, contract_bytes_v3(), digest_text_v3())
    } else if program_uses_vec(program) {
        (SCHEMA_V2, contract_bytes_v2(), digest_text_v2())
    } else {
        (SCHEMA_V1, contract_bytes_v1(), digest_text_v1())
    }
}

fn case_index(cases: &[VariantCaseDeclaration], case: &VariantCaseDeclaration) -> usize {
    cases
        .iter()
        .position(|candidate| std::ptr::eq(candidate, case))
