            assert!(contract.contains(fact), "missing {fact}");
        }
        assert_eq!(
            digest_text_v4(),
            "sha256:04d6c7bcff11395cfe72c429f6cf1b076f766fdbabba423edbb02e1692d1fd89"
        );
