/// Read-only replay measuring `FrontendPass::lookup`'s `Program::clone` cost
/// (SPX-AI-031/#130, SPX-AI-032/#131). See that module's doc comment.
mod clone_cost_report;
pub(crate) mod paid_resolution;
mod source_handoff;
