//! The `Enter` frame: the first visit to an expression, which either
//! produces a value directly or schedules the frames its operands need.

use crate::ast::{Expr, ExprKind, ImportResult, ParamMode, Statement, Type, TypeDeclarationKind};
use crate::diagnostic::Diagnostic;
use crate::source_verify::arguments::{
    activate_borrowed_bytes_call_loans, source_byte_view_place_is_admitted,
};
use crate::source_verify::binding::{Availability, CheckedValue};
use crate::source_verify::declared_type::{
    check_declared_type, function_value_signature, generic_function_arguments_are_admitted,
    generic_function_arguments_are_forwarded, validation_specialize_signature,
};
use crate::source_verify::diagnostics::{error, source_identifier};
use crate::source_verify::hints;
use crate::source_verify::place::{
    check_source_place_availability, overlapping_place_state, source_place,
};
use crate::source_verify::scope::{
    VerifierCallTarget, VerifierFrame, VerifierFunctionSignature, VerifierScope,
};
use crate::source_verify::type_table::effective_record_fields;
use crate::source_verify::IterativeVerifier;
use std::collections::HashSet;

#[cfg(test)]
mod enter_before_components;
#[cfg(test)]
mod enter_before_extended;

impl<'a, 'p> IterativeVerifier<'a, 'p> {
    pub(super) fn frame_enter(
        &mut self,
        expression: &'p Expr,
        scope: usize,
    ) -> Result<(), Diagnostic> {
        #[cfg(test)]
        if self.extended_before_799 {
            return self.before_extended_frame_enter(expression, scope);
        }
        #[cfg(test)]
        if self.operators_before_799 {
            return self.before_components_frame_enter(expression, scope);
        }
        #[cfg(test)]
        if self.recovery_legacy {
            return self.recovery_old_frame_enter(expression, scope);
        }

        self.recovery.begin(expression);
        match &expression.kind {
            ExprKind::VecConstructor { .. } => {
                let hygienic = *self.constructor_hygiene.get_or_insert_with(|| {
                    crate::ast::expression_statement::projection_roots(
                        self.current
                            .requires
                            .iter()
                            .chain(std::iter::once(&self.current.body))
                            .chain(&self.current.ensures),
                        self.current
                            .params
                            .iter()
                            .map(|param| param.name.as_str())
                            .chain(
                                self.current
                                    .type_parameters
                                    .iter()
                                    .map(|param| param.name.as_str()),
                            ),
                        crate::bounded_output::reserve_active_required,
                    )
                });
                if !hygienic {
                    return Err(error(
                        self.program,
                        "SPX-T318",
                        "Vec constructor generated owner names are not hygienic",
                        expression.span,
                    ));
                }
                let expansion = crate::ast::vec_constructor::inspect(expression)
                    .map_err(|message| error(self.program, "SPX-T318", message, expression.span))?;
                self.frames.push(VerifierFrame::Enter {
                    expression: expansion.value,
                    scope,
                });
            }
            ExprKind::LexicalExit { kind, value } => {
                if let Some(operand) = value {
                    self.frames.push(VerifierFrame::ResumeLexicalReturn {
                        expression,
                        operand,
                        scope,
                    });
                    self.frames.push(VerifierFrame::Enter {
                        expression: operand,
                        scope,
                    });
                } else if *kind != crate::ast::LexicalExitKind::Return {
                    self.values.push(Some(CheckedValue::value(Type::Never)));
                } else {
                    return Err(error(
                        self.program,
                        "SPX-T312",
                        "return requires an operand",
                        expression.span,
                    ));
                }
            }
            ExprKind::Closure { .. } => self.enter_closure(expression, scope)?,
            ExprKind::Int(_) => self.values.push(Some(CheckedValue::value(Type::I64))),
            ExprKind::Int32(_) => self.values.push(Some(CheckedValue::value(Type::I32))),
            ExprKind::Char(_) => self.values.push(Some(CheckedValue::value(Type::Char))),
            ExprKind::Uint8(_) => self.values.push(Some(CheckedValue::value(Type::U8))),
            ExprKind::Usize(_) => self.values.push(Some(CheckedValue::value(Type::Usize))),
            ExprKind::ArrayU8(values) => self.values.push(Some(CheckedValue::value(
                Type::ArrayU8(values.len() as u32),
            ))),
            ExprKind::RepeatArrayU8 { count, .. } => self
                .values
                .push(Some(CheckedValue::value(Type::ArrayU8(*count)))),
            ExprKind::Float32(_) => self.values.push(Some(CheckedValue::value(Type::F32))),
            ExprKind::Float64(_) => self.values.push(Some(CheckedValue::value(Type::F64))),
            ExprKind::Bool(_) => self.values.push(Some(CheckedValue::value(Type::Bool))),
            ExprKind::String(_) => self.values.push(Some(CheckedValue::value(Type::String))),
            ExprKind::BorrowedUtf8Literal(text) => {
                self.values
                    .push(Some(crate::source_verify::static_text::checked(
                        self.program,
                        expression.span,
                        text,
                    )?))
            }
            ExprKind::Var(name) if name == "result" => {
                if self.result_type.is_some() && self.recovery.reads_value(scope, name, expression)
                {
                    self.values.push(None);
                    return Ok(());
                }
                let value = self
                    .result_type
                    .map(|ty| CheckedValue::returned(ty.clone(), self.types.needs_drop(ty)));
                if value.is_none() {
                    self.diagnostics.push(
                        error(
                            self.program,
                            "SPX-T201",
                            "`result` is only available in postconditions",
                            expression.span,
                        )
                        .with_help(hints::RESULT_NAME_HELP),
                    );
                }
                self.values.push(value);
            }
            ExprKind::Var(name) => {
                if self.scopes[scope]
                    .bindings
                    .get(name)
                    .is_some_and(|binding| binding.traversal_row.is_some())
                    && !self
                        .row_loan_sites
                        .contains(&(expression.span.start, expression.span.end))
                {
                    return Err(error(
                        self.program,
                        "SPX-T284",
                        "record traversal row cannot escape or materialize aggregate storage; select a field",
                        expression.span,
                    ));
                }
                let value = self.scopes[scope].bindings.get(name).map(|binding| {
                    crate::source_verify::owning_closure::reject_escaping_read(
                        self.program,
                        name,
                        &binding.ty,
                        expression.span,
                        self.diagnostics,
                    );
                    match binding.availability {
                        Availability::Moved => self.diagnostics.push(
                            error(
                                self.program,
                                "SPX-O101",
                                format!("use of resource `{name}` after ownership was moved"),
                                expression.span,
                            )
                            .with_help(crate::source_verify::hints::moved_resource_help(
                                &binding.ty,
                                name,
                            )),
                        ),
                        Availability::MaybeMoved => self.diagnostics.push(
                            error(
                                self.program,
                                "SPX-O107",
                                format!("resource `{name}` may have been moved on another control-flow path"),
                                expression.span,
                            )
                            .with_help(crate::source_verify::hints::moved_resource_help(
                                &binding.ty,
                                name,
                            )),
                        ),
                        Availability::Available => match overlapping_place_state(binding, &[]) {
                            Availability::Moved => self.diagnostics.push(
                                error(self.program, "SPX-O109", format!("use of partially moved place `{name}`"), expression.span)
                                    .with_help("use an available sibling field or avoid moving this place earlier"),
                            ),
                            Availability::MaybeMoved => self.diagnostics.push(
                                error(self.program, "SPX-O110", format!("place `{name}` may have been moved on another control-flow path"), expression.span)
                                    .with_help("move the field on every path or keep it borrowed"),
                            ),
                            Availability::Available => {}
                        },
                    }
                    if binding.native_unit_discard {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-B107",
                            "Native Rust Interop declaration set is unsupported: scalar value signature required",
                            expression.span,
                        ));
                    }
                    CheckedValue { ty: binding.ty.clone(), mode: binding.mode, native_unit: binding.native_unit_discard }
                });
                let value = value.or_else(|| {
                    self.functions
                        .get(name.as_str())
                        .and_then(|function| function_value_signature(function))
                        .map(CheckedValue::value)
                });
                if value.is_none() && !self.recovery.reads_refused(scope, name) {
                    self.diagnostics.push(hints::with_optional_help(
                        error(
                            self.program,
                            "SPX-T202",
                            format!("unknown value `{name}` in `{}`", self.current.name),
                            expression.span,
                        ),
                        hints::variant_shorthand_help(name).map(str::to_owned),
                    ));
                }
                // Preserve every real binding/ownership check above before
                // attaching a separate expected-type refusal view to this read.
                let refused = value.is_some() && self.recovery.reads_value(scope, name, expression);
                self.values.push(if refused { None } else { value });
            }
            ExprKind::Unary { op, value } => {
                self.frames.push(VerifierFrame::ResumeUnary {
                    expression,
                    operand: value,
                    op: *op,
                });
                self.frames.push(VerifierFrame::Enter {
                    expression: value,
                    scope,
                });
            }
            ExprKind::Binary { op, left, right } => {
                self.frames.push(VerifierFrame::ResumeBinaryLeft {
                    expression,
                    op: *op,
                    right,
                    scope,
                });
                self.frames.push(VerifierFrame::Enter {
                    expression: left,
                    scope,
                });
            }
            ExprKind::Call {
                name,
                type_arguments,
                args,
            } => {
                let args: &[Expr] = if name == crate::vec_ops::sort_keys::NAME {
                    if !self.current.type_parameters.is_empty()
                        || crate::source_verify::sort_keys::descriptor(
                            self.types,
                            type_arguments,
                            args,
                        )
                        .is_none()
                    {
                        self.diagnostics.push(error(self.program,"SPX-T311","vec_sort_by requires an explicit monomorphic record and 1..8 unique literal field:asc/field:desc keys",expression.span));
                        self.values.push(None);
                        return Ok(());
                    }
                    &args[..1]
                } else if name == crate::vec_ops::field_unique::NAME {
                    if !self.current.type_parameters.is_empty()
                        || crate::source_verify::field_unique::descriptor(
                            self.types,
                            type_arguments,
                            args,
                            &self.scopes[scope].bindings,
                        )
                        .is_none()
                    {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T319",
                            crate::vec_ops::field_unique::SHAPE,
                            expression.span,
                        ));
                        self.values.push(None);
                        return Ok(());
                    }
                    &args[..1]
                } else {
                    args
                };
                if let Some(result) = crate::source_verify::owning_closure::check_call(
                    self.program,
                    name,
                    type_arguments,
                    args,
                    expression.span,
                    self.allow_moves,
                    &mut self.scopes[scope].bindings,
                    self.types,
                    self.diagnostics,
                ) {
                    self.values.push(result);
                    return Ok(());
                }
                let native = self
                    .program
                    .interfaces()
                    .iter()
                    .flat_map(|interface| &interface.imports)
                    .find(|import| import.native_rust && import.name == *name);
                let callable_binding = self.scopes[scope].bindings.get(name).map(|binding| {
                    crate::source_verify::mutable_closure::invocation_signature(
                        self.program,
                        binding,
                        name,
                        args,
                        self.allow_moves,
                        expression.span,
                        self.diagnostics,
                    )
                });
                let target = if let Some(binding_type) = callable_binding {
                    match binding_type {
                        Type::Function { parameters, result } => {
                            if !type_arguments.is_empty() {
                                self.diagnostics.push(error(
                                    self.program,
                                    "SPX-T225",
                                    "function values do not accept type arguments",
                                    expression.span,
                                ));
                            }
                            if args.len() != parameters.len() {
                                self.diagnostics.push(error(
                                    self.program,
                                    "SPX-T204",
                                    format!(
                                        "`{name}` expects {} arguments, received {}",
                                        parameters.len(),
                                        args.len()
                                    ),
                                    expression.span,
                                ));
                            }
                            VerifierCallTarget::Ordinary(Some(
                                VerifierFunctionSignature::Specialized {
                                    params: parameters
                                        .into_iter()
                                        .enumerate()
                                        .map(|(index, ty)| crate::ast::Param {
                                            name: format!("argument{index}"),
                                            mode: ParamMode::Value,
                                            ty,
                                            span: expression.span,
                                        })
                                        .collect(),
                                    return_type: *result,
                                    implicit_unique_ownership: false,
                                },
                            ))
                        }
                        _ => {
                            self.diagnostics.push(error(
                                self.program,
                                "SPX-T287",
                                format!("`{name}` is a bound value, not a function value"),
                                expression.span,
                            ));
                            VerifierCallTarget::Ordinary(None)
                        }
                    }
                } else if let Some(import) = native {
                    if !type_arguments.is_empty() || args.len() != import.params.len() {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-B107",
                            "Native Rust Interop declaration set is unsupported: scalar value signature required",
                            expression.span,
                        ));
                    }
                    for effect in &import.effects {
                        if !self.current.effects.contains(effect) {
                            self.diagnostics.push(error(
                                self.program,
                                "SPX-B107",
                                "Native Rust Interop declaration set is unsupported: effect or capability mismatch",
                                expression.span,
                            ));
                        }
                    }
                    VerifierCallTarget::Native(import)
                } else if let Some(op) = crate::map_ops::by_generic_name(name, type_arguments) {
                    let Some((params, return_type)) = op.ast_signature(type_arguments) else {
                        return Err(error(
                            self.program,
                            "SPX-T274",
                            "typed collection requires admitted key/value type arguments",
                            expression.span,
                        ));
                    };
                    if args.len() != params.len() {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T204",
                            format!(
                                "`{name}` expects {} arguments, received {}",
                                params.len(),
                                args.len()
                            ),
                            expression.span,
                        ));
                    }
                    VerifierCallTarget::Ordinary(Some(VerifierFunctionSignature::Specialized {
                        params,
                        return_type,
                        implicit_unique_ownership: false,
                    }))
                } else if name == crate::vec_field::NAME {
                    let Some((params, return_type)) = super::super::vec_field::signature(
                        self.types,
                        type_arguments,
                        args,
                        expression.span,
                    ) else {
                        self.diagnostics.push(error(self.program,"SPX-T310","vec_field requires one admitted owned record type, a named Vec and usize index, and an exact literal field selector",expression.span));
                        self.values.push(None);
                        return Ok(());
                    };
                    if !self.current.type_parameters.is_empty() {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T310",
                            "vec_field is not admitted in generic function templates",
                            expression.span,
                        ));
                    }
                    VerifierCallTarget::Ordinary(Some(VerifierFunctionSignature::Specialized {
                        params,
                        return_type,
                        implicit_unique_ownership: false,
                    }))
                } else if name == crate::literal_format::NAME {
                    if !type_arguments.is_empty() {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T225",
                            "string_format does not accept type arguments",
                            expression.span,
                        ));
                    }
                    if !self.current.type_parameters.is_empty() {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T225",
                            "string_format is not admitted in generic function templates",
                            expression.span,
                        ));
                    }
                    let template = match args.first().map(|arg| &arg.kind) {
                        Some(ExprKind::String(value)) => value,
                        _ => {
                            self.diagnostics.push(error(self.program, "SPX-T204", "string_format requires a compile-time string literal as its first argument", expression.span));
                            self.values.push(None);
                            return Ok(());
                        }
                    };
                    let pieces = match crate::literal_format::scan(template) {
                        Ok(pieces) => pieces,
                        Err(reason) => {
                            self.diagnostics.push(error(
                                self.program,
                                "SPX-T204",
                                reason.message(),
                                args[0].span,
                            ));
                            self.values.push(None);
                            return Ok(());
                        }
                    };
                    let fields = crate::literal_format::field_count(&pieces);
                    if args.len() - 1 != fields {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T204",
                            format!(
                                "string_format literal has {fields} fields, received {} values",
                                args.len() - 1
                            ),
                            expression.span,
                        ));
                    }
                    VerifierCallTarget::LiteralFormat
                } else if let Some(op) = crate::string_ops::by_name(name) {
                    // Compiler-owned string operations verify through
                    // the ordinary monomorphic machinery with one
                    // synthetic signature; consuming arguments use the
                    // established `own` transfer mode and borrowed
                    // arguments never mark their sources moved.
                    if op == crate::string_ops::StringOp::Take
                        && !crate::string_ops::take::source_operand(args, self.allow_moves)
                    {
                        self.diagnostics.push(error(self.program, "SPX-O105",
                            "string_take requires an available named owned String outside contracts", expression.span));
                    }
                    let params = crate::string_ops::ast_params(op);
                    if !type_arguments.is_empty() {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T225",
                            format!("monomorphic function `{name}` does not accept type arguments"),
                            expression.span,
                        ));
                    }
                    if args.len() != params.len() {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T204",
                            format!(
                                "`{name}` expects {} arguments, received {}",
                                params.len(),
                                args.len()
                            ),
                            expression.span,
                        ));
                    }
                    VerifierCallTarget::Ordinary(Some(VerifierFunctionSignature::Specialized {
                        params,
                        return_type: op.ast_return_type(),
                        implicit_unique_ownership: false,
                    }))
                } else if let Some(op) = crate::str_ops::by_name(name) {
                    let params = crate::str_ops::ast_params(op);
                    if !type_arguments.is_empty() {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T225",
                            format!("monomorphic function `{name}` does not accept type arguments"),
                            expression.span,
                        ));
                    }
                    if args.len() != params.len() {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T204",
                            format!(
                                "`{name}` expects {} arguments, received {}",
                                params.len(),
                                args.len()
                            ),
                            expression.span,
                        ));
                    }
                    VerifierCallTarget::Ordinary(Some(VerifierFunctionSignature::Specialized {
                        params,
                        return_type: op.ast_return_type(),
                        implicit_unique_ownership: false,
                    }))
                } else if let Some(op) = crate::vec_ops::by_name(name) {
                    if op == crate::vec_ops::VecOp::StrAt
                        && (!self.current.type_parameters.is_empty()
                            || crate::source_verify::string_slot::root(
                                type_arguments,
                                args,
                                &self.scopes[scope].bindings,
                            )
                            .is_none())
                    {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T281",
                            crate::vec_ops::string_slot::SHAPE,
                            expression.span,
                        ));
                    }
                    let element = if op == crate::vec_ops::VecOp::StrAt {
                        Some(&Type::String)
                    } else {
                        type_arguments.first()
                    };
                    if (if op == crate::vec_ops::VecOp::StrAt { !type_arguments.is_empty() } else { type_arguments.len() != 1 })
                        || element.is_none_or(|ty| {
                            !crate::source_verify::declared_type::owned_leaf_collection::vec_operation_admitted(self.types, op, ty)
                                && !crate::vec_ops::source_parameter_is_admitted(self.program, self.current, op, ty)
                        })
                    {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T281",
                            format!("vector operation `{name}` requires one explicit admitted type argument"),
                            expression.span,
                        ));
                    }
                    if args.len() != op.arity() {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T281",
                            format!(
                                "vector operation `{name}` expects {} arguments, received {}",
                                op.arity(),
                                args.len()
                            ),
                            expression.span,
                        ));
                    }
                    if op.capacity_argument().is_some_and(|index| {
                        matches!(args.get(index).map(|arg| &arg.kind), Some(ExprKind::Usize(value)) if *value > crate::vec_ops::MAX_CAPACITY)
                    })
                    {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T282",
                            format!(
                                "`{name}` literal capacity must be no greater than {}",
                                crate::vec_ops::MAX_CAPACITY
                            ),
                            expression.span,
                        ));
                    }
                    VerifierCallTarget::Ordinary(element.map(|element| {
                        VerifierFunctionSignature::Specialized {
                            params: crate::vec_ops::ast_params_with_owned_element(
                                op,
                                element,
                                *element == crate::ast::Type::Bytes
                                    || crate::source_verify::declared_type::owned_leaf_collection::admitted(self.types, element)
                                    || crate::source_verify::declared_type::
                                        owned_leaf_collection::runtime_element(
                                            self.types, element,
                                        ),
                            ),
                            return_type: op.ast_return_type(element),
                            implicit_unique_ownership: false,
                        }
                    }))
                } else if let Some(op) = crate::list_ops::by_name(name) {
                    if !type_arguments.is_empty() || args.len() != op.argument_count() {
                        self.diagnostics.push(error(self.program, "SPX-T291", format!("immutable list operation `{name}` requires {} arguments and no type arguments", op.argument_count()), expression.span));
                    }
                    VerifierCallTarget::Ordinary(Some(VerifierFunctionSignature::Specialized {
                        params: op.ast_params(),
                        return_type: op.ast_return_type(),
                        implicit_unique_ownership: false,
                    }))
                } else if let Some(op) = crate::iterator_ops::by_name(name) {
                    let element = type_arguments.first();
                    if type_arguments.len() != 1
                        || args.len() != 1
                        || element.is_none_or(|ty| {
                            !crate::iterator_ops::ast_element_is_admitted(ty)
                                    && !crate::source_verify::declared_type::
                                        owned_leaf_collection::runtime_element(
                                            self.types,
                                            ty,
                                        )
                        })
                    {
                        self.diagnostics.push(error(self.program,"SPX-T290","iterator operations require one concrete scalar type argument and one owned argument",expression.span));
                    }
                    VerifierCallTarget::Ordinary(element.map(|element| {
                        VerifierFunctionSignature::Specialized {
                            params: crate::iterator_ops::ast_params(op, element),
                            return_type: op.ast_return_type(element),
                            implicit_unique_ownership: false,
                        }
                    }))
                } else if let Some(op) = crate::box_ops::by_name(name) {
                    let element = type_arguments.first();
                    if type_arguments.len() != 1
                        || element.is_none_or(|ty| {
                            !crate::box_ops::ast_operation_element_is_admitted(op, ty)
                                && !crate::box_ops::source_parameter_is_admitted(
                                    self.program,
                                    self.current,
                                    op,
                                    ty,
                                )
                        })
                    {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T285",
                            format!("box operation `{name}` requires one explicit admitted type argument"),
                            expression.span,
                        ));
                    }
                    if args.len() != 1 {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T285",
                            format!(
                                "box operation `{name}` expects 1 argument, received {}",
                                args.len()
                            ),
                            expression.span,
                        ));
                    }
                    VerifierCallTarget::Ordinary(element.map(|element| {
                        VerifierFunctionSignature::Specialized {
                            params: crate::box_ops::ast_params(op, element),
                            return_type: op.ast_return_type(element),
                            implicit_unique_ownership: false,
                        }
                    }))
                } else if let Some(op) = crate::byte_ops::by_name(name) {
                    if !type_arguments.is_empty() {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T263",
                            format!("byte operation `{name}` does not accept type arguments"),
                            expression.span,
                        ));
                    }
                    if args.len() != op.arity() {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T263",
                            format!(
                                "byte operation `{name}` expects {} arguments, received {}",
                                op.arity(),
                                args.len()
                            ),
                            expression.span,
                        ));
                    }
                    if op.is_view()
                        && args.first().is_none_or(|argument| {
                            !source_byte_view_place_is_admitted(
                                op,
                                argument,
                                &self.scopes[scope].bindings,
                                self.types,
                            )
                        })
                    {
                        let diagnostic = error(
                            self.program,
                            "SPX-T266",
                            if matches!(
                                op,
                                crate::byte_ops::ByteOp::StringAsStr
                                    | crate::byte_ops::ByteOp::StrAsBytes
                            ) {
                                format!(
                                    "borrowed view `{name}` requires a named String owner or an authenticated named-record path to a String field"
                                )
                            } else {
                                format!(
                                    "borrowed view `{name}` requires an exact admitted storage place"
                                )
                            },
                            expression.span,
                        );
                        self.diagnostics.push(match args.first() {
                            Some(argument) => {
                                diagnostic.with_help(hints::view_place_help(name, argument))
                            }
                            None => diagnostic,
                        });
                    }
                    if op.is_owned_buffer_chain() {
                        let reopen = self
                            .buffer_reopen_sites
                            .contains(&(expression.span.start, expression.span.end));
                        self.diagnostics
                            .extend(crate::source_verify::owned_buffer::check_call(
                                self.program,
                                expression,
                                op,
                                name,
                                args,
                                reopen,
                            ));
                    }
                    VerifierCallTarget::Byte(op)
                } else if let Some(op) = crate::host_io_ops::by_name(name) {
                    let params = crate::host_io_ops::ast_params(op);
                    if !type_arguments.is_empty() || args.len() != params.len() {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T269",
                            format!("invalid host I/O operation `{name}` call shape"),
                            expression.span,
                        ));
                    }
                    VerifierCallTarget::HostIo(op)
                } else if let Some(op) = crate::stdin_stream_ops::pure_by_name(name) {
                    if !type_arguments.is_empty() || args.len() != 1 {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T270",
                            "invalid streaming stdin inspection call shape",
                            expression.span,
                        ));
                    }
                    VerifierCallTarget::Ordinary(Some(VerifierFunctionSignature::Specialized {
                        params: op.params(),
                        return_type: op.ast_result(),
                        implicit_unique_ownership: false,
                    }))
                } else if let Some(op) = crate::command_io_ops::by_name(name) {
                    let params = crate::command_io_ops::ast_params(op);
                    if !type_arguments.is_empty() || args.len() != params.len() {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T270",
                            format!("invalid command I/O operation `{name}` call shape"),
                            expression.span,
                        ));
                    }
                    VerifierCallTarget::CommandIo(op)
                } else {
                    let target = self.functions.get(name.as_str()).copied();
                    if target.is_none() {
                        self.diagnostics.push(hints::unknown_function(
                            self.program,
                            name,
                            self.functions,
                            expression.span,
                        ));
                    }
                    if target.is_some_and(|target| args.len() != target.params.len()) {
                        let target = target.expect("checked above");
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T204",
                            format!(
                                "`{name}` expects {} arguments, received {}",
                                target.params.len(),
                                args.len()
                            ),
                            expression.span,
                        ));
                    }
                    let specialized = target.and_then(|target| {
                        if target.type_parameters.is_empty() {
                            if !type_arguments.is_empty() {
                                self.diagnostics.push(error(
                                    self.program,
                                    "SPX-T225",
                                    format!("monomorphic function `{name}` does not accept type arguments"),
                                    expression.span,
                                ));
                                return None;
                            }
                            return Some(VerifierFunctionSignature::Borrowed(target));
                        }
                        let inferred_arguments;
                        let type_arguments = if type_arguments.is_empty() {
                            inferred_arguments = crate::source_verify::generic_inference::arguments(
                                self.program,
                                self.current,
                                target,
                                args,
                                &self.scopes[scope].bindings,
                                self.functions,
                                self.types,
                            );
                            inferred_arguments.as_deref().unwrap_or(type_arguments)
                        } else {
                            type_arguments
                        };
                        if type_arguments.len() != target.type_parameters.len() {
                            self.diagnostics.push(error(
                                self.program,
                                "SPX-T225",
                                format!("generic function `{name}` expects {} explicit type arguments, received {}", target.type_parameters.len(), type_arguments.len()),
                                expression.span,
                            ).with_help(hints::generic_call_help(name)));
                            return None;
                        }
                        if !generic_function_arguments_are_admitted(target, type_arguments, self.types)
                            && !generic_function_arguments_are_forwarded(
                                self.current,
                                target,
                                type_arguments,
                            )
                            && !crate::vec_ops::source_arguments_are_admitted(
                                self.program,
                                target,
                                type_arguments,
                            )
                            && !crate::box_ops::source_arguments_are_admitted(self.program, target, type_arguments)
                        {
                            self.diagnostics.push(error(
                                self.program,
                                "SPX-T225",
                                format!("generic function `{name}` accepts only direct `i64` or `bool` type arguments, except admitted Copy scalars in an owned-record relay"),
                                expression.span,
                            ));
                            return None;
                        }
                        validation_specialize_signature(target, type_arguments).map(
                            |(params, return_type)| {
                                VerifierFunctionSignature::SourceSpecialized {
                                    function: target,
                                    params,
                                    return_type,
                                }
                            },
                        )
                    });
                    VerifierCallTarget::Ordinary(specialized)
                };
                if let VerifierCallTarget::Ordinary(Some(VerifierFunctionSignature::Borrowed(
                    function,
                ))) = &target
                {
                    self.note_row_loan_arguments(function, args, scope);
                }
                let borrowed_bytes_loans = match &target {
                    VerifierCallTarget::Ordinary(Some(VerifierFunctionSignature::Borrowed(
                        function,
                    ))) => activate_borrowed_bytes_call_loans(
                        self.program,
                        args,
                        &function.params,
                        &mut self.scopes[scope].bindings,
                        self.types,
                    ),
                    VerifierCallTarget::Ordinary(Some(
                        VerifierFunctionSignature::Specialized { params, .. }
                        | VerifierFunctionSignature::SourceSpecialized { params, .. },
                    )) if params.iter().any(|p| {
                        crate::source_verify::declared_type::collection_record::vector(
                            self.types, &p.ty,
                        )
                    }) =>
                    {
                        activate_borrowed_bytes_call_loans(
                            self.program,
                            args,
                            params,
                            &mut self.scopes[scope].bindings,
                            self.types,
                        )
                    }
                    _ => Vec::new(),
                };
                if let Some(argument) = args.first() {
                    self.frames.push(VerifierFrame::ResumeCallArgument {
                        expression,
                        name,
                        args,
                        scope,
                        index: 0,
                        target,
                        borrowed_bytes_loans,
                    });
                    self.frames.push(VerifierFrame::Enter {
                        expression: argument,
                        scope,
                    });
                } else {
                    if self.refused_callee_return(&target) {
                        self.values.push(None);
                        return Ok(());
                    }
                    self.values.push(Some(match target {
                        VerifierCallTarget::LiteralFormat => {
                            CheckedValue::returned(Type::String, true)
                        }
                        VerifierCallTarget::Native(import) => {
                            let mut value = CheckedValue::returned(
                                import.result.value_type(),
                                import.result.is_owned(),
                            );
                            value.native_unit = import.result == ImportResult::Unit;
                            value
                        }
                        VerifierCallTarget::Byte(op) => {
                            let ty = op.ast_return_type();
                            let owns = self.types.needs_drop(&ty);
                            CheckedValue::returned(ty, owns)
                        }
                        VerifierCallTarget::HostIo(op) => {
                            CheckedValue::returned(op.ast_return_type(), false)
                        }
                        VerifierCallTarget::CommandIo(op) => CheckedValue {
                            ty: crate::command_io_ops::ast_return_type(op),
                            mode: match op {
                                crate::hir::ResolvedHostCommandOperation::ArgUtf8 => {
                                    ParamMode::Borrow
                                }
                                crate::hir::ResolvedHostCommandOperation::StdinRead => {
                                    ParamMode::Own
                                }
                                crate::hir::ResolvedHostCommandOperation::ArgsLen
                                | crate::hir::ResolvedHostCommandOperation::StderrWrite
                                | crate::hir::ResolvedHostCommandOperation::StdoutAppend
                                | crate::hir::ResolvedHostCommandOperation::StderrAppend => {
                                    ParamMode::Value
                                }
                                operation => {
                                    match crate::command_io_ops::result_ownership(operation) {
                                        crate::hir::OwnershipMode::Own => ParamMode::Own,
                                        crate::hir::OwnershipMode::Borrow => ParamMode::Borrow,
                                        _ => ParamMode::Value,
                                    }
                                }
                            },
                            native_unit: false,
                        },
                        VerifierCallTarget::Ordinary(Some(target)) => CheckedValue::returned(
                            target.return_type().clone(),
                            self.types.needs_drop(target.return_type()),
                        ),
                        VerifierCallTarget::Ordinary(None) => {
                            self.values.push(None);
                            return Ok(());
                        }
                    }));
                }
            }
            ExprKind::MethodCall {
                receiver,
                method,
                type_arguments,
                args,
                ..
            } => {
                if !type_arguments.is_empty() {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-T225",
                        format!("method `{method}` does not accept type arguments in this slice"),
                        expression.span,
                    ));
                }
                self.frames.push(VerifierFrame::ResumeMethodReceiver {
                    expression,
                    receiver,
                    method,
                    args,
                    scope,
                });
                self.frames.push(VerifierFrame::Enter {
                    expression: receiver,
                    scope,
                });
            }
            // These walkers only traverse generic-function and contract
            // expressions; `super` is meaningful only inside a class-method
            // override, whose body is resolved by the HIR layer instead.
            ExprKind::SuperMethod { method_span, .. } => {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-T231",
                    "`super` is only allowed inside a class-method override",
                    *method_span,
                ));
                self.values.push(None);
            }
            ExprKind::If {
                condition,
                then_branch,
                else_branch,
            } => {
                self.frames.push(VerifierFrame::ResumeIfCondition {
                    expression,
                    then_branch,
                    else_branch,
                    scope,
                });
                self.frames.push(VerifierFrame::Enter {
                    expression: condition,
                    scope,
                });
            }
            ExprKind::Block { statements, tail } => {
                let outer_names = self.scopes[scope]
                    .bindings
                    .keys()
                    .cloned()
                    .collect::<Vec<_>>();
                let block_scope = self.scopes.len();
                self.recovery.fork(Some(scope), block_scope);
                self.scopes.push(VerifierScope {
                    bindings: self.scopes[scope].bindings.clone(),
                    local_borrow_count: self.scopes[scope].local_borrow_count,
                });
                if let Some(first_statement) = statements.first() {
                    if let Statement::Let {
                        name, name_span, ..
                    } = first_statement
                    {
                        if !source_identifier(name) {
                            self.diagnostics.push(hints::reserved_local_binding(
                                self.program,
                                name,
                                *name_span,
                            ));
                        }
                    }
                    if let Statement::While {
                        condition, body, ..
                    } = first_statement
                    {
                        self.begin_while_statement(
                            expression,
                            statements,
                            tail,
                            scope,
                            block_scope,
                            0,
                            outer_names,
                            condition,
                            body,
                        );
                    } else if let Statement::For {
                        item,
                        item_span,
                        values,
                        body,
                        ..
                    }
                    | Statement::ForBorrow {
                        item,
                        item_span,
                        values,
                        body,
                        ..
                    }
                    | Statement::ForOwn {
                        item,
                        item_span,
                        values,
                        body,
                        ..
                    } = first_statement
                    {
                        self.begin_for_statement(
                            expression,
                            statements,
                            tail,
                            scope,
                            block_scope,
                            0,
                            outer_names,
                            item,
                            *item_span,
                            values,
                            body,
                        );
                    } else {
                        self.check_string_replacement_entry(first_statement, block_scope);
                        self.note_owned_buffer_reopen(first_statement);
                        self.frames.push(VerifierFrame::ResumeBlockStatement {
                            expression,
                            statements,
                            tail,
                            parent_scope: scope,
                            block_scope,
                            index: 0,
                            outer_names,
                            recovery_checkpoint: self.recovery.checkpoint(self.diagnostics),
                        });
                        self.frames.push(VerifierFrame::Enter {
                            expression: first_statement.value(),
                            scope: block_scope,
                        });
                    }
                } else {
                    self.frames.push(VerifierFrame::ResumeBlockTail {
                        parent_scope: scope,
                        block_scope,
                        outer_names,
                    });
                    self.frames.push(VerifierFrame::Enter {
                        expression: tail,
                        scope: block_scope,
                    });
                }
            }
            // Resumable Effects v1 (issue #204). See
            // `iterative::calls::frame_resume_yield`.
            ExprKind::Yield { request } => {
                self.frames.push(VerifierFrame::ResumeYield {
                    expression,
                    request,
                });
                self.frames.push(VerifierFrame::Enter {
                    expression: request,
                    scope,
                });
            }
            ExprKind::Try { operand } => {
                self.frames.push(VerifierFrame::ResumeTry {
                    expression,
                    operand,
                    scope,
                });
                self.frames.push(VerifierFrame::Enter {
                    expression: operand,
                    scope,
                });
            }
            ExprKind::Project { base, field, .. } => {
                if let Some((root, value)) = crate::source_verify::record_traversal::project(
                    expression,
                    &self.scopes[scope].bindings,
                    self.types,
                ) {
                    let owner = Expr {
                        kind: ExprKind::Var(root),
                        span: expression.span,
                    };
                    if let Some(place) =
                        source_place(&owner, &self.scopes[scope].bindings, self.types)
                    {
                        check_source_place_availability(
                            self.program,
                            &place,
                            &self.scopes[scope].bindings,
                            expression.span,
                            self.diagnostics,
                        );
                    }
                    self.values.push(Some(value));
                    return Ok(());
                }
                let rooted_string_view = matches!(
                    self.frames.last(),
                    Some(VerifierFrame::ResumeCallArgument {
                        target: VerifierCallTarget::Byte(crate::byte_ops::ByteOp::StringAsStr),
                        ..
                    })
                ) && source_byte_view_place_is_admitted(
                    crate::byte_ops::ByteOp::StringAsStr,
                    expression,
                    &self.scopes[scope].bindings,
                    self.types,
                );
                if self.loop_depth != 0 && !rooted_string_view
                    && source_place(base, &self.scopes[scope].bindings, self.types).is_some_and(
                        |place| {
                            !crate::source_verify::declared_type::owned_leaf_collection::copy_or_leaf_admitted(
                                self.types, &place.ty,
                            ) && !crate::source_verify::declared_type::collection_record::admitted(&place.ty, self.types)
                        },
                    )
                {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-T252",
                        "record field projection is not yet admitted in while bodies",
                        expression.span,
                    ));
                }
                if let Some(place) =
                    source_place(expression, &self.scopes[scope].bindings, self.types)
                {
                    check_source_place_availability(
                        self.program,
                        &place,
                        &self.scopes[scope].bindings,
                        expression.span,
                        self.diagnostics,
                    );
                    self.publish_source_place(place, scope);
                } else {
                    self.frames.push(VerifierFrame::ResumeProject {
                        expression,
                        base,
                        field,
                    });
                    self.frames.push(VerifierFrame::Enter {
                        expression: base,
                        scope,
                    });
                }
            }
            ExprKind::ConstructRecord {
                type_name,
                type_arguments,
                fields,
                ..
            } => {
                if matches!(type_name.as_str(), "Map" | "Set") {
                    return Err(error(
                        self.program,
                        "SPX-T274",
                        "collections can only be created by map_new/set_new",
                        expression.span,
                    ));
                }
                if type_name == "Iter" {
                    return Err(error(
                        self.program,
                        "SPX-T290",
                        "Iter carriers can only be created by vec_into_iter",
                        expression.span,
                    ));
                }
                let instance = Type::Named {
                    name: type_name.clone(),
                    arguments: type_arguments.clone(),
                };
                let reported = self.diagnostics.len();
                check_declared_type(
                    self.program,
                    &instance,
                    expression.span,
                    self.types,
                    &HashSet::new(),
                    self.diagnostics,
                );
                let declared_fields = effective_record_fields(self.types, &instance);
                if declared_fields.is_none()
                    && !self.diagnostics[reported..]
                        .iter()
                        .any(|diagnostic| diagnostic.severity.is_error())
                {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-T215",
                        format!("`{type_name}` is not a declared record type"),
                        expression.span,
                    ));
                }
                if !fields.is_empty() {
                    self.frames.push(VerifierFrame::PrepareRecordField {
                        expression,
                        type_name,
                        type_arguments,
                        fields,
                        declared_fields,
                        scope,
                        index: 0,
                        supplied: HashSet::new(),
                    });
                } else {
                    if let Some(declared_fields) = declared_fields {
                        for field in declared_fields {
                            self.diagnostics.push(error(
                                self.program,
                                "SPX-T213",
                                format!(
                                    "record `{type_name}` construction is missing field `{}`",
                                    field.name
                                ),
                                expression.span,
                            ));
                        }
                        self.values.push(Some(CheckedValue::returned(
                            instance.clone(),
                            self.types.needs_drop(&instance),
                        )));
                    } else {
                        self.values.push(None);
                    }
                }
            }
            ExprKind::ConstructVariant {
                type_name,
                type_arguments,
                case_name,
                fields,
                ..
            } => {
                let declaration = self.types.declaration(type_name);
                let instance = Type::Named {
                    name: type_name.clone(),
                    arguments: type_arguments.clone(),
                };
                check_declared_type(
                    self.program,
                    &instance,
                    expression.span,
                    self.types,
                    &HashSet::new(),
                    self.diagnostics,
                );
                let cases = declaration.and_then(|declaration| match &declaration.kind {
                    TypeDeclarationKind::Variant { cases } => Some(cases.as_slice()),
                    TypeDeclarationKind::Resource { .. }
                    | TypeDeclarationKind::Record { .. }
                    | TypeDeclarationKind::Class { .. } => None,
                });
                let case =
                    cases.and_then(|cases| cases.iter().find(|case| case.name == *case_name));
                if cases.is_none() || case.is_none() {
                    let diagnostic = error(
                        self.program,
                        "SPX-T215",
                        format!("`{type_name}::{case_name}` is not a declared variant constructor"),
                        expression.span,
                    );
                    self.diagnostics.push(
                        match cases.and_then(|cases| {
                            crate::source_verify::hints::nearest_variant_case_name(case_name, cases)
                        }) {
                            Some(nearest) => diagnostic.with_help(format!(
                                "did you mean `{type_name}::{nearest} {{ ... }}`?"
                            )),
                            None => diagnostic,
                        },
                    );
                }
                if !fields.is_empty() {
                    self.frames.push(VerifierFrame::PrepareVariantField {
                        expression,
                        type_name,
                        type_arguments,
                        case_name,
                        fields,
                        declaration,
                        case,
                        scope,
                        index: 0,
                        supplied: HashSet::new(),
                    });
                } else {
                    if let Some(case) = case {
                        for field in &case.fields {
                            self.diagnostics.push(error(self.program, "SPX-T213", format!("variant construction `{type_name}::{case_name}` is missing payload field `{}`", field.name), expression.span));
                        }
                        // Ownership belongs to the complete variant carrier, not
                        // only to the selected case. A zero-payload case of a
                        // variant whose other cases contain owned fields is still
                        // a fresh owned carrier and must cross return/call
                        // boundaries exactly once.
                        self.values.push(Some(CheckedValue::returned(
                            instance.clone(),
                            self.types.needs_drop(&instance),
                        )));
                    } else if cases.is_some() {
                        self.values.push(Some(CheckedValue::returned(
                            instance.clone(),
                            self.types.needs_drop(&instance),
                        )));
                    } else {
                        self.values.push(None);
                    }
                }
            }
            ExprKind::UpdateRecord { base, fields } => {
                self.frames.push(VerifierFrame::ResumeUpdateBase {
                    expression,
                    base,
                    fields,
                    scope,
                });
                self.frames.push(VerifierFrame::Enter {
                    expression: base,
                    scope,
                });
            }
            ExprKind::Match {
                scrutinee, arms, ..
            } => {
                self.frames.push(VerifierFrame::ResumeMatchScrutinee {
                    checkpoint: self.recovery.checkpoint(self.diagnostics),
                    expression,
                    scrutinee,
                    arms,
                    scope,
                });
                self.frames.push(VerifierFrame::Enter {
                    expression: scrutinee,
                    scope,
                });
            }
        }
        Ok(())
    }
}

edits.new:
//! Compiler-owned operations for the internal Owned Bounded Vec v1 profile.

use crate::ast::program_source::ProgramSource;
use crate::ast::{Expr, ExprKind, Param, ParamMode, Span, Type};
use crate::hir::{
    DeclarationId, OwnershipMode, ResolvedExpr, ResolvedExprKind, ResolvedParam, ResolvedType,
    ValueId,
};

mod by_id_metered;
pub(crate) mod field_unique;
pub(crate) mod field_update;
mod sort;
pub(crate) mod sort_keys;
pub(crate) mod string_slot;
mod wrappers;
pub(crate) use by_id_metered::by_id_with_work;
pub(crate) use sort::{program_uses_sort, resolved_program_uses_sort};
pub(crate) use wrappers::*;
#[cfg(test)]
mod owned_payload_tests;

pub(crate) const WITH_CAPACITY_NAME: &str = "vec_with_capacity";
pub(crate) const PUSH_NAME: &str = "vec_push";
pub(crate) const LEN_NAME: &str = "vec_len";
pub(crate) const CAPACITY_NAME: &str = "vec_capacity";
pub(crate) const GET_NAME: &str = "vec_get";
pub(crate) const RESERVE_EXACT_NAME: &str = "vec_reserve_exact";
pub(crate) const SET_NAME: &str = "vec_set";
pub(crate) const CLEAR_NAME: &str = "vec_clear";
pub(crate) const SORT_NAME: &str = "vec_sort";
pub(crate) const WITH_CAPACITY_ID: &str = "core.vec.with-capacity";
pub(crate) const PUSH_ID: &str = "core.vec.push";
pub(crate) const LEN_ID: &str = "core.vec.len";
pub(crate) const CAPACITY_ID: &str = "core.vec.capacity";
pub(crate) const GET_ID: &str = "core.vec.get";
pub(crate) const RESERVE_EXACT_ID: &str = "core.vec.reserve-exact";
pub(crate) const SET_ID: &str = "core.vec.set";
pub(crate) const CLEAR_ID: &str = "core.vec.clear";
pub(crate) const SORT_ID: &str = "core.vec.sort";
pub(crate) const CLONE_AT_NAME: &str = "vec_clone_at";
pub(crate) const REPLACE_NAME: &str = "vec_replace";
pub(crate) const RESERVE_OWNED_NAME: &str = "vec_reserve_owned";
pub(crate) const SORT_OWNED_NAME: &str = "vec_sort_owned";
pub(crate) const CLONE_AT_ID: &str = "core.vec.clone-at";
pub(crate) const REPLACE_ID: &str = "core.vec.replace";
pub(crate) const RESERVE_OWNED_ID: &str = "core.vec.reserve-owned";
pub(crate) const SORT_OWNED_ID: &str = "core.vec.sort-owned";
pub(crate) const MAX_CAPACITY: u64 = 8_192;
pub(crate) const OWNED_PAYLOAD_BYTES_PER_ELEMENT: u64 = 16;
pub(crate) const MAX_OWNED_PAYLOAD_BYTES: u64 = 131_072;
pub(crate) const STATUS_DOMAIN: &str = "semaprax.vec.v1";
pub(crate) const PUSH_FULL_CODE: u32 = 1;
pub(crate) const GET_OUT_OF_BOUNDS_CODE: u32 = 2;
pub(crate) const ALLOCATION_FAILURE_CODE: u32 = 3;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) enum VecOp {
    WithCapacity,
    Push,
    Len,
    Capacity,
    Get,
    ReserveExact,
    Set,
    Clear,
    Sort,
    CloneAt,
    Replace,
    ReserveOwned,
    SortOwned,
    SortBy,
    StrAt,
    UniqueBy,
    UpdateField,
}

pub(crate) const ALL: [VecOp; 17] = [
    VecOp::WithCapacity,
    VecOp::Push,
    VecOp::Len,
    VecOp::Capacity,
    VecOp::Get,
    VecOp::ReserveExact,
    VecOp::Set,
    VecOp::Clear,
    VecOp::Sort,
    VecOp::CloneAt,
    VecOp::Replace,
    VecOp::ReserveOwned,
    VecOp::SortOwned,
    VecOp::SortBy,
    VecOp::StrAt,
    VecOp::UniqueBy,
    VecOp::UpdateField,
];

impl VecOp {
    pub(crate) const fn owned_leaf_only(self) -> bool {
        matches!(
            self,
            Self::CloneAt
                | Self::Replace
                | Self::ReserveOwned
                | Self::SortOwned
                | Self::StrAt
                | Self::UpdateField
        )
    }
    pub(crate) const fn admits_owned_leaf(self) -> bool {
        matches!(
            self,
            Self::WithCapacity | Self::Push | Self::Len | Self::Capacity | Self::Clear
        ) || self.owned_leaf_only()
            || matches!(self, Self::SortBy | Self::UniqueBy)
    }

    pub(crate) const fn reopens_same_owner(self) -> bool {
        matches!(
            self,
            Self::Push
                | Self::ReserveExact
                | Self::Set
                | Self::Clear
                | Self::Sort
                | Self::Replace
                | Self::UpdateField
                | Self::ReserveOwned
                | Self::SortOwned
                | Self::SortBy
        )
    }

    pub(crate) const fn returns_owner(self) -> bool {
        matches!(
            self,
            Self::WithCapacity
                | Self::Push
                | Self::ReserveExact
                | Self::Set
                | Self::Clear
                | Self::Sort
                | Self::CloneAt
                | Self::Replace
                | Self::UpdateField
                | Self::ReserveOwned
                | Self::SortOwned
                | Self::SortBy
        )
    }

    pub(crate) const fn admitted_in_while(self) -> bool {
        matches!(
            self,
            Self::Push
                | Self::Len
                | Self::Capacity
                | Self::Get
                | Self::StrAt
                | Self::Set
                | Self::Clear
                | Self::Sort
                | Self::ReserveExact
                | Self::CloneAt
                | Self::Replace
                | Self::UpdateField
                | Self::ReserveOwned
                | Self::SortOwned
                | Self::SortBy
        )
    }

    pub(crate) const fn capacity_argument(self) -> Option<usize> {
        match self {
            Self::WithCapacity => Some(0),
            Self::ReserveExact | Self::ReserveOwned => Some(1),
            _ => None,
        }
    }
    pub(crate) const fn name(self) -> &'static str {
        match self {
            Self::WithCapacity => WITH_CAPACITY_NAME,
            Self::Push => PUSH_NAME,
            Self::Len => LEN_NAME,
            Self::Capacity => CAPACITY_NAME,
            Self::Get => GET_NAME,
            Self::ReserveExact => RESERVE_EXACT_NAME,
            Self::Set => SET_NAME,
            Self::Clear => CLEAR_NAME,
            Self::Sort => SORT_NAME,
            Self::CloneAt => CLONE_AT_NAME,
            Self::Replace => REPLACE_NAME,
            Self::ReserveOwned => RESERVE_OWNED_NAME,
            Self::SortOwned => SORT_OWNED_NAME,
            Self::SortBy => sort_keys::NAME,
            Self::StrAt => string_slot::NAME,
            Self::UniqueBy => field_unique::NAME,
            Self::UpdateField => field_update::NAME,
        }
    }
    pub(crate) const fn id(self) -> &'static str {
        match self {
            Self::WithCapacity => WITH_CAPACITY_ID,
            Self::Push => PUSH_ID,
            Self::Len => LEN_ID,
            Self::Capacity => CAPACITY_ID,
            Self::Get => GET_ID,
            Self::ReserveExact => RESERVE_EXACT_ID,
            Self::Set => SET_ID,
            Self::Clear => CLEAR_ID,
            Self::Sort => SORT_ID,
            Self::CloneAt => CLONE_AT_ID,
            Self::Replace => REPLACE_ID,
            Self::ReserveOwned => RESERVE_OWNED_ID,
            Self::SortOwned => SORT_OWNED_ID,
            Self::SortBy => sort_keys::PREFIX,
            Self::StrAt => string_slot::ID,
            Self::UniqueBy => field_unique::PREFIX,
            Self::UpdateField => field_update::PREFIX,
        }
    }
    pub(crate) const fn arity(self) -> usize {
        match self {
            Self::WithCapacity => 1,
            Self::Push => 2,
            Self::Len | Self::Capacity | Self::UniqueBy => 1,
            Self::Get | Self::CloneAt | Self::StrAt => 2,
            Self::ReserveExact | Self::ReserveOwned => 2,
            Self::Set | Self::Replace | Self::UpdateField => 3,
            Self::Clear | Self::Sort | Self::SortOwned | Self::SortBy => 1,
        }
    }
    pub(crate) const fn param_ownership(self, index: usize) -> OwnershipMode {
        match (self, index) {
            (
                Self::Push
                | Self::ReserveExact
                | Self::Set
                | Self::Clear
                | Self::Sort
                | Self::Replace
                | Self::UpdateField
                | Self::ReserveOwned
                | Self::SortOwned
                | Self::SortBy,
                0,
            ) => OwnershipMode::Own,
            (
                Self::Len
                | Self::Capacity
                | Self::Get
                | Self::CloneAt
                | Self::StrAt
                | Self::UniqueBy,
                0,
            ) => OwnershipMode::Borrow,
            _ => OwnershipMode::Value,
        }
    }
    /// The element slot's ownership mode.
    ///
    /// An owned element transfers into the collection at the call's commit
    /// boundary instead of being copied. `Bytes` does, and so does the one
    /// admitted owned-record collection element (SPX-AI-019), which is the
    /// only `ResolvedType::Nominal` any admission path lets reach here:
    /// Copy scalars are primitive variants and a generic collection's element
    /// is a `ResolvedType::TypeParameter`, so neither is matched. An element
    /// outside every admitted profile is refused with a stable diagnostic in
    /// source and HIR before this function is consulted.
    pub(crate) const fn param_ownership_for(
        self,
        index: usize,
        element: &ResolvedType,
    ) -> OwnershipMode {
        if matches!(
            element,
            ResolvedType::Bytes | ResolvedType::String | ResolvedType::Nominal { .. }
        ) && matches!(
            (self, index),
            (Self::Push, 1) | (Self::Set | Self::Replace, 2)
        ) {
            OwnershipMode::Own
        } else {
            self.param_ownership(index)
        }
    }
    pub(crate) fn resolved_return_type(self, element: &ResolvedType) -> ResolvedType {
        match self {
            Self::WithCapacity
            | Self::Push
            | Self::ReserveExact
            | Self::Set
            | Self::Clear
            | Self::Sort
            | Self::Replace
            | Self::UpdateField
            | Self::ReserveOwned
            | Self::SortOwned
            | Self::SortBy => resolved_vec(element.clone()),
            Self::Len | Self::Capacity => ResolvedType::Usize,
            Self::Get | Self::CloneAt => element.clone(),
            Self::StrAt => ResolvedType::Str,
            Self::UniqueBy => ResolvedType::Bool,
        }
    }
    pub(crate) fn ast_return_type(self, element: &Type) -> Type {
        match self {
            Self::WithCapacity
            | Self::Push
            | Self::ReserveExact
            | Self::Set
            | Self::Clear
            | Self::Sort
            | Self::Replace
            | Self::UpdateField
            | Self::ReserveOwned
            | Self::SortOwned
            | Self::SortBy => ast_vec(element.clone()),
            Self::Len | Self::Capacity => Type::Usize,
            Self::Get | Self::CloneAt => element.clone(),
            Self::StrAt => Type::Str,
            Self::UniqueBy => Type::Bool,
        }
    }
    pub(crate) fn accepts_resolved(
        self,
        index: usize,
        ty: &ResolvedType,
        element: &ResolvedType,
    ) -> bool {
        if self == Self::StrAt && *element != ResolvedType::String {
            return false;
        }
        match (self, index) {
            (Self::WithCapacity, 0) => *ty == ResolvedType::Usize,
            (Self::Push, 0)
            | (
                Self::Len
                | Self::Capacity
                | Self::Get
                | Self::CloneAt
                | Self::StrAt
                | Self::UniqueBy,
                0,
            ) => resolved_vec_matches(ty, element),
            (Self::Push, 1) => ty == element,
            (Self::Get | Self::CloneAt | Self::StrAt, 1) => *ty == ResolvedType::Usize,
            (Self::ReserveExact | Self::ReserveOwned, 0)
            | (Self::Set | Self::Replace | Self::UpdateField, 0)
            | (Self::Clear | Self::Sort | Self::SortOwned | Self::SortBy, 0) => {
                resolved_vec_matches(ty, element)
            }
            (Self::ReserveExact | Self::ReserveOwned, 1)
            | (Self::Set | Self::Replace | Self::UpdateField, 1) => *ty == ResolvedType::Usize,
            (Self::Set | Self::Replace, 2) => ty == element,
            (Self::UpdateField, 2) => resolved_element_is_admitted(ty),
            _ => false,
        }
    }
}

/// Exact equality to resolved_vec without constructing its temporary owners.
pub(crate) fn resolved_vec_matches(ty: &ResolvedType, element: &ResolvedType) -> bool {
    matches!(ty, ResolvedType::Nominal { declaration, arguments }
        if declaration.as_str() == crate::prelude::VEC_ID
            && arguments.as_slice() == std::slice::from_ref(element))
}

pub(crate) fn by_name(name: &str) -> Option<VecOp> {
    match name {
        WITH_CAPACITY_NAME => Some(VecOp::WithCapacity),
        PUSH_NAME => Some(VecOp::Push),
        LEN_NAME => Some(VecOp::Len),
        CAPACITY_NAME => Some(VecOp::Capacity),
        GET_NAME => Some(VecOp::Get),
        RESERVE_EXACT_NAME => Some(VecOp::ReserveExact),
        SET_NAME => Some(VecOp::Set),
        CLEAR_NAME => Some(VecOp::Clear),
        SORT_NAME => Some(VecOp::Sort),
        CLONE_AT_NAME => Some(VecOp::CloneAt),
        REPLACE_NAME => Some(VecOp::Replace),
        RESERVE_OWNED_NAME => Some(VecOp::ReserveOwned),
        SORT_OWNED_NAME => Some(VecOp::SortOwned),
        sort_keys::NAME => Some(VecOp::SortBy),
        string_slot::NAME => Some(VecOp::StrAt),
        field_unique::NAME => Some(VecOp::UniqueBy),
        field_update::NAME => Some(VecOp::UpdateField),
        _ => None,
    }
}
pub(crate) fn by_id(id: &str) -> Option<VecOp> {
    if id.starts_with(sort_keys::PREFIX) {
        return Some(VecOp::SortBy);
    }
    if id.starts_with(field_unique::PREFIX) {
        return Some(VecOp::UniqueBy);
    }
    if id.starts_with(field_update::PREFIX) {
        return Some(VecOp::UpdateField);
    }
    match id {
        string_slot::ID | string_slot::BYTES_ID => Some(VecOp::StrAt),
        WITH_CAPACITY_ID => Some(VecOp::WithCapacity),
        PUSH_ID => Some(VecOp::Push),
        LEN_ID => Some(VecOp::Len),
        CAPACITY_ID => Some(VecOp::Capacity),
        GET_ID => Some(VecOp::Get),
        RESERVE_EXACT_ID => Some(VecOp::ReserveExact),
        SET_ID => Some(VecOp::Set),
        CLEAR_ID => Some(VecOp::Clear),
        SORT_ID => Some(VecOp::Sort),
        CLONE_AT_ID => Some(VecOp::CloneAt),
        REPLACE_ID => Some(VecOp::Replace),
        RESERVE_OWNED_ID => Some(VecOp::ReserveOwned),
        SORT_OWNED_ID => Some(VecOp::SortOwned),
        _ => None,
    }
}
pub(crate) fn ast_element_is_admitted(ty: &Type) -> bool {
    matches!(
        ty,
        Type::I64
            | Type::I32
            | Type::U8
            | Type::Usize
            | Type::Char
            | Type::F32
            | Type::F64
            | Type::Bool
    )
}
/// Exact compiler-owned Copy-scalar Vec spelling before HIR identity resolution.
pub(crate) fn ast_copy_vec(ty: &Type) -> bool {
    matches!(ty, Type::Named { name, arguments }
        if name == "Vec" && matches!(arguments.as_slice(), [element] if ast_element_is_admitted(element)))
}
pub(crate) fn resolved_element_is_admitted(ty: &ResolvedType) -> bool {
    matches!(
        ty,
        ResolvedType::I64
            | ResolvedType::I32
            | ResolvedType::U8
            | ResolvedType::Usize
            | ResolvedType::Char
            | ResolvedType::F32
            | ResolvedType::F64
            | ResolvedType::Bool
    )
}
/// Exact compiler-owned Copy-scalar Vec identity after HIR resolution.
pub(crate) fn resolved_copy_vec(ty: &ResolvedType) -> bool {
    matches!(ty, ResolvedType::Nominal { declaration, arguments }
        if declaration.as_str() == crate::prelude::VEC_ID
            && matches!(arguments.as_slice(), [element] if resolved_element_is_admitted(element)))
}
/// Scalar admission remains frozen for generic wrappers. Bytes is admitted only
/// by the owning intrinsic Vec boundary.
pub(crate) fn ast_vec_element_is_admitted(ty: &Type) -> bool {
    ast_element_is_admitted(ty) || *ty == Type::Bytes
}
pub(crate) fn resolved_vec_element_is_admitted(ty: &ResolvedType) -> bool {
    resolved_element_is_admitted(ty) || *ty == ResolvedType::Bytes
}
pub(crate) fn ast_operation_element_is_admitted(op: VecOp, ty: &Type) -> bool {
    !op.owned_leaf_only()
        && !matches!(op, VecOp::SortBy | VecOp::UniqueBy)
        && (ast_element_is_admitted(ty)
            || (*ty == Type::Bytes && !matches!(op, VecOp::Get | VecOp::Sort)))
}
pub(crate) fn resolved_operation_element_is_admitted(op: VecOp, ty: &ResolvedType) -> bool {
    !op.owned_leaf_only()
        && !matches!(op, VecOp::SortBy | VecOp::UniqueBy)
        && (resolved_element_is_admitted(ty)
            || (*ty == ResolvedType::Bytes && !matches!(op, VecOp::Get | VecOp::Sort)))
}
pub(crate) fn ast_vec(element: Type) -> Type {
    Type::Named {
        name: "Vec".to_owned(),
        arguments: vec![element],
    }
}
pub(crate) fn resolved_vec(element: ResolvedType) -> ResolvedType {
    ResolvedType::Nominal {
        declaration: DeclarationId::compiler(crate::hir::CompilerDeclaration::Vec),
        arguments: vec![element],
    }
}
#[cfg(test)]
pub(crate) fn ast_params(op: VecOp, element: &Type) -> Vec<Param> {
    ast_params_with_owned_element(op, element, matches!(element, Type::Bytes | Type::String))
}

/// `ast_params`, with the element slot's transfer mode supplied by the caller.
///
/// The source verifier cannot decide from the spelling alone whether a
/// `Type::Named` element is the admitted owned-record collection element or a
/// generic wrapper's type parameter — both are `Named` with no arguments — so
/// the classifier's answer is threaded in rather than guessed here. Passing
/// `false` reproduces the pre-SPX-AI-019 Copy-element signature exactly.
pub(crate) fn ast_params_with_owned_element(
    op: VecOp,
    element: &Type,
    owned_element: bool,
) -> Vec<Param> {
    let types = match op {
        VecOp::WithCapacity => vec![Type::Usize],
        VecOp::Push => vec![ast_vec(element.clone()), element.clone()],
        VecOp::Len | VecOp::Capacity | VecOp::UniqueBy => vec![ast_vec(element.clone())],
        VecOp::Get | VecOp::CloneAt | VecOp::StrAt => vec![ast_vec(element.clone()), Type::Usize],
        VecOp::ReserveExact | VecOp::ReserveOwned => vec![ast_vec(element.clone()), Type::Usize],
        VecOp::Set | VecOp::Replace => vec![ast_vec(element.clone()), Type::Usize, element.clone()],
        VecOp::UpdateField => vec![ast_vec(element.clone()), Type::Usize, Type::I64],
        VecOp::Clear | VecOp::Sort | VecOp::SortOwned | VecOp::SortBy => {
            vec![ast_vec(element.clone())]
        }
    };
    types
        .into_iter()
        .enumerate()
        .map(|(index, ty)| Param {
            name: format!("arg{index}"),
            mode: match if owned_element
                && matches!(
                    (op, index),
                    (VecOp::Push, 1) | (VecOp::Set | VecOp::Replace, 2)
                ) {
                OwnershipMode::Own
            } else {
                op.param_ownership(index)
            } {
                OwnershipMode::Own => ParamMode::Own,
                OwnershipMode::Borrow => ParamMode::Borrow,
                _ => ParamMode::Value,
            },
            ty,
            span: Span::default(),
        })
        .collect()
}
pub(crate) fn resolved_params(op: VecOp, element: &ResolvedType) -> Vec<ResolvedParam> {
    let types = match op {
        VecOp::WithCapacity => vec![ResolvedType::Usize],
        VecOp::Push => vec![resolved_vec(element.clone()), element.clone()],
        VecOp::Len | VecOp::Capacity | VecOp::UniqueBy => vec![resolved_vec(element.clone())],
        VecOp::Get | VecOp::CloneAt | VecOp::StrAt => {
            vec![resolved_vec(element.clone()), ResolvedType::Usize]
        }
        VecOp::ReserveExact | VecOp::ReserveOwned => {
            vec![resolved_vec(element.clone()), ResolvedType::Usize]
        }
        VecOp::UpdateField => vec![
            resolved_vec(element.clone()),
            ResolvedType::Usize,
            ResolvedType::I64,
        ],
        VecOp::Set | VecOp::Replace => vec![
            resolved_vec(element.clone()),
            ResolvedType::Usize,
            element.clone(),
        ],
        VecOp::Clear | VecOp::Sort | VecOp::SortOwned | VecOp::SortBy => {
            vec![resolved_vec(element.clone())]
        }
    };
    types
        .into_iter()
        .enumerate()
        .map(|(index, ty)| ResolvedParam {
            id: ValueId::intrinsic_parameter(op.id(), index),
            name: format!("arg{index}"),
            ownership: op.param_ownership_for(index, element),
            ty,
            span: Span::default(),
        })
        .collect()
}

/// Resolve the nominal element mode from authenticated declaration facts.
pub(crate) fn resolved_params_in(
    declarations: &crate::hir::DeclarationIndex,
    op: VecOp,
    element: &ResolvedType,
) -> Vec<ResolvedParam> {
    let mut params = resolved_params(op, element);
    if crate::hir::copy_record_collection::admitted(declarations, element) {
        for (index, parameter) in params.iter_mut().enumerate() {
            parameter.ownership = op.param_ownership(index);
        }
    }
    params
}

/// True when the source requests the owning Bytes Vec profile. An authored
/// `Vec` declaration remains ordinary source meaning.
pub(crate) fn program_uses_owned_payload(program: &dyn ProgramSource) -> bool {
    if program.types().iter().any(|declaration| {
        declaration.name == "Vec" && declaration.stable_id != crate::prelude::VEC_ID
    }) {
        return false;
    }
    fn has_vec_bytes(ty: &Type) -> bool {
        matches!(ty, Type::Named { name, arguments }
            if name == "Vec" && matches!(arguments.as_slice(), [Type::Bytes]))
            || matches!(ty, Type::Named { arguments, .. } if arguments.iter().any(has_vec_bytes))
    }
    let function_uses = |function: &crate::ast::Function| {
        function.params.iter().any(|param| has_vec_bytes(&param.ty))
            || has_vec_bytes(&function.return_type)
            || function
                .requires
                .iter()
                .chain(std::iter::once(&function.body))
                .chain(&function.ensures)
                .any(|expr| {
                    let mut found = false;
                    expr.visit_call_instances(&mut |name, arguments, _| {
                        found |= matches!(by_name(name), Some(op) if !matches!(op, VecOp::Get | VecOp::Sort))
                            && matches!(arguments, [Type::Bytes]);
                    });
                    found
                })
    };
    program.functions().iter().any(function_uses)
}

pub(crate) fn resolved_program_uses_owned_payload(program: &crate::hir::ResolvedProgram) -> bool {
    if crate::iterator_ops::resolved_program_uses_owned_iterator(program) {
        return true;
    }
    fn has_vec_bytes(ty: &ResolvedType) -> bool {
        matches!(ty, ResolvedType::Nominal { declaration, arguments }
            if declaration.as_str() == crate::prelude::VEC_ID
                && matches!(arguments.as_slice(), [ResolvedType::Bytes]))
            || matches!(ty, ResolvedType::Nominal { arguments, .. }
                if arguments.iter().any(has_vec_bytes))
    }
    let function_uses = |function: &crate::hir::ResolvedFunction| {
        function.params.iter().any(|param| has_vec_bytes(&param.ty))
            || has_vec_bytes(&function.return_type)
            || std::iter::once(&function.body)
                .chain(function.requires.iter())
                .chain(function.ensures.iter())
                .any(|root| {
                    let mut found = false;
                    crate::hir::visit_resolved_calls(root, &mut |callee, instance, arguments| {
                        found |= instance.is_none()
                            && matches!(by_id(callee.as_str()), Some(op) if !matches!(op, VecOp::Get | VecOp::Sort))
                            && matches!(arguments, [ResolvedType::Bytes]);
                    });
                    found
                })
    };
    program
        .functions
        .iter()
        .chain(
            program
                .function_instances
                .iter()
                .map(|instance| &instance.function),
        )
        .any(function_uses)
}

pub(crate) fn is_same_owner_reassignment_source(
    program: &dyn ProgramSource,
    value: &Expr,
    name: &str,
    ty: &Type,
) -> bool {
    let ExprKind::Call {
        name: callee,
        type_arguments,
        args,
    } = &value.kind
    else {
        return false;
    };
    let direct = by_name(callee).filter(|op| op.reopens_same_owner());
    let wrapper = program
        .functions()
        .iter()
        .find(|function| function.name == *callee)
        .and_then(|function| source_wrapper(program, function))
        .filter(|op| op.reopens_same_owner());
    let op = direct.or(wrapper);
    let owner_type_matches = match type_arguments.as_slice() {
        [element] => ast_vec(element.clone()) == *ty,
        [] if direct.is_none() && wrapper.is_some() => matches!(
            ty,
            Type::Named { name, arguments }
                if name == "Vec"
                    && matches!(arguments.as_slice(), [element] if ast_element_is_admitted(element))
        ),
        _ => false,
    };
    // The literal policy is an authored source operand. Resolution encodes it
    // into the authenticated callee descriptor, leaving only the owning Vec.
    op.is_some_and(|op| {
        args.len()
            == op.arity() + usize::from(matches!(direct, Some(VecOp::SortBy | VecOp::UpdateField)))
    }) && owner_type_matches
        && matches!(&args[0].kind, ExprKind::Var(source) if source == name)
}

pub(crate) fn is_same_owner_reassignment_hir(
    program: &crate::hir::ResolvedProgram,
    value: &ResolvedExpr,
    owner: &ValueId,
) -> bool {
    let ResolvedExprKind::Call {
        callee,
        type_arguments,
        instance,
        args,
    } = &value.kind
    else {
        return false;
    };
    let op = if instance.is_none() {
        by_id(callee.as_str()).filter(|op| op.reopens_same_owner())
    } else {
        instance.as_ref().and_then(|instance| {
            (crate::hir::FunctionInstanceId::derive(callee, type_arguments) == *instance)
                .then(|| {
                    program
                        .function_templates
                        .iter()
                        .find(|template| template.id == *callee)
                        .and_then(|template| hir_wrapper_in_program(program, template))
                        .filter(|op| op.reopens_same_owner())
                })
                .flatten()
        })
    };
    op.is_some_and(|op| args.len() == op.arity())
        && matches!(type_arguments.as_slice(), [argument] if resolved_vec_element_is_admitted(argument) || crate::hir::owned_leaf_collection::copy_or_leaf_admitted(&program.declarations, argument))
        && matches!(&args[0].kind, ResolvedExprKind::Place(place)
            if &place.root == owner && place.projections.is_empty())
}

pub(crate) fn is_same_owner_reassignment_hir_source(
    program: &dyn ProgramSource,
    value: &ResolvedExpr,
    owner: &ValueId,
) -> bool {
    let ResolvedExprKind::Call {
        callee,
        type_arguments,
        instance,
        args,
    } = &value.kind
    else {
        return false;
    };
    let op = if instance.is_none() {
        by_id(callee.as_str()).filter(|op| op.reopens_same_owner())
    } else {
        instance.as_ref().and_then(|instance| {
            (crate::hir::FunctionInstanceId::derive(callee, type_arguments) == *instance)
                .then(|| {
                    program
                        .functions()
                        .iter()
                        .find(|function| function.stable_id == callee.as_str())
                        .and_then(|function| source_wrapper(program, function))
                        .filter(|op| op.reopens_same_owner())
                })
                .flatten()
        })
    };
    op.is_some_and(|op| args.len() == op.arity())
        && matches!(type_arguments.as_slice(), [argument] if resolved_vec_element_is_admitted(argument) || crate::source_verify::copy_record_resolved_source_admitted(program, argument) || crate::source_verify::owned_leaf_resolved_source_admitted(program, argument))
        && matches!(&args[0].kind, ResolvedExprKind::Place(place)
            if &place.root == owner && place.projections.is_empty())
}

